-- =======================================================================
-- 0001_schema_core.sql
-- =======================================================================
-- 0001_schema_core.sql
-- Platform v2 core schema: enum types, profiles, admin bootstrap list, and the
-- catalog tables (products, quizzes, pack_quizzes, questions).
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline,
-- the questions lockdown, and every policy live in the 0005-0010 migrations.
-- Triggers and helper functions live in 0003.
--
-- Requirements: 3.3, 9.8, 26.1, 27.11, 35.1, 35.2, 35.3

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Enum types
-- ---------------------------------------------------------------------------
-- Statuses are enums rather than text-with-check so an invalid value cannot be
-- written even by the service role.

create type product_type      as enum ('material', 'quiz_pack');
create type order_status      as enum ('pending', 'paid', 'failed', 'refunded');
create type enrollment_source as enum ('purchase', 'comp', 'credit');
create type referral_status   as enum ('available', 'paid', 'void');
create type reward_type       as enum ('cash', 'credit');
create type incident_kind     as enum ('amount_mismatch', 'currency_mismatch',
                                       'unmatched_payment', 'unmatched_refund',
                                       'out_of_order_status', 'self_referral');

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
-- One row per auth.users row, inserted by the on_auth_user_created trigger
-- (migration 0003). Requirement 3.3: ref_code uniqueness is a constraint, not a
-- convention.

create table public.profiles (
  id           uuid primary key references auth.users(id) on delete cascade,
  email        text not null,
  display_name text,
  is_admin     boolean not null default false,
  ref_code     text not null unique,
  referred_by  text references public.profiles(ref_code),
  gcash_number text,
  created_at   timestamptz not null default now()
);

comment on column public.profiles.is_admin is
  'Set by handle_new_user() from admin_bootstrap_emails. Never writable by a client role: see the column-level update grant and guard_profile_columns().';

-- ---------------------------------------------------------------------------
-- admin_bootstrap_emails
-- ---------------------------------------------------------------------------
-- Requirement 26.1. Admin bootstrap is data, not a hardcoded list inside the
-- trigger, so appointing an admin before their first login is a service-role
-- insert rather than a migration edit. Service-role only: no grants, no
-- policies (migrations 0005 and 0009).

create table public.admin_bootstrap_emails (
  email text primary key
);

insert into public.admin_bootstrap_emails (email)
values ('rehinaneel@gmail.com'), ('nairutya.84@gmail.com'), ('nairutya.iitp@gmail.com')
on conflict (email) do nothing;

-- Requirement 26.1 for profiles that already exist when this migration runs.
-- A no-op on a fresh database; the trigger in 0003 covers rows created later.
update public.profiles p
set is_admin = true
where exists (
  select 1 from public.admin_bootstrap_emails b
  where b.email = lower(p.email)
) and p.is_admin = false;

-- ---------------------------------------------------------------------------
-- products
-- ---------------------------------------------------------------------------
-- Requirement 27.11: price_php is a positive integer, slug is unique, and type
-- is constrained by the enum, so an invalid product save fails at the database
-- even if the Admin_Function validation is bypassed.
-- Requirement 35.1: the seed import maps v1 'material'/'quiz' onto
-- 'material'/'quiz_pack' and preserves title, subject, description, price, and
-- sort order.
-- material_path is never granted to a client role (migration 0008);
-- thumbnail_path is, because thumbnails live in a separate public bucket.

create table public.products (
  id             uuid primary key default gen_random_uuid(),
  slug           text not null unique,
  type           product_type not null,
  subject        text,
  title          text not null,
  subtitle       text,
  description    text,
  price_php      integer not null check (price_php > 0),
  currency       char(3) not null default 'PHP' check (currency = 'PHP'),
  thumbnail_path text,
  material_path  text,
  includes       jsonb not null default '[]'::jsonb,
  published      boolean not null default false,
  sort_order     integer not null default 0,
  created_at     timestamptz not null default now()
);

comment on column public.products.material_path is
  'Object path in the private Materials_Bucket. Withheld from the anon/authenticated select grant so the browser never learns the object layout.';

-- Supports the published-only catalog read ordered by sort_order.
create index products_published_sort_idx on public.products (published, sort_order);

-- ---------------------------------------------------------------------------
-- quizzes
-- ---------------------------------------------------------------------------
-- Requirement 9.8: metadata only. Question content lives in public.questions,
-- which no client role can reach at all.
-- Requirement 35.2: one row per distinct v1 quiz_id, preserving title, subject,
-- and timer_minutes.

create table public.quizzes (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,
  title         text not null,
  subject       text,
  timer_minutes integer not null default 0 check (timer_minutes >= 0),
  published     boolean not null default false,
  created_at    timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- pack_quizzes
-- ---------------------------------------------------------------------------
-- Maps quiz-pack products to the quizzes they unlock. Visibility follows the
-- parent product's published flag (policy in migration 0008).

create table public.pack_quizzes (
  product_id uuid not null references public.products(id) on delete cascade,
  quiz_id    uuid not null references public.quizzes(id) on delete cascade,
  sort_order integer not null default 0,
  primary key (product_id, quiz_id)
);

-- ---------------------------------------------------------------------------
-- questions
-- ---------------------------------------------------------------------------
-- Requirement 35.3: one row per v1 question, preserving text, options, the
-- correct option as correct_key, and the explanation.
-- The answer-key guarantee (Requirement 6) is enforced in migration 0006 by
-- granting nothing to anon/authenticated and defining zero policies. Do not add
-- a client grant or policy here.

create table public.questions (
  id              uuid primary key default gen_random_uuid(),
  quiz_id         uuid not null references public.quizzes(id) on delete cascade,
  question_number integer not null,
  question_text   text not null,
  options         jsonb not null,
  correct_key     text not null,
  explanation     text,
  created_at      timestamptz not null default now(),
  unique (quiz_id, question_number)
);

comment on table public.questions is
  'Answer keys. Reachable only by service_role. No anon/authenticated grant and no RLS policy may ever be added: see migration 0006.';

-- =======================================================================
-- 0002_schema_money.sql
-- =======================================================================
-- 0002_schema_money.sql
-- Platform v2 money and access schema: orders, enrollments, quiz_attempts,
-- referrals, payment_incidents, payout_requests.
--
-- Depends on 0001_schema_core.sql for pgcrypto, the enum types
-- (order_status, enrollment_source, referral_status, reward_type,
-- incident_kind) and the profiles/products/quizzes tables. Those types are
-- reused here, never redeclared.
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline
-- and every policy live in the 0005-0010 migrations; fulfil_payment,
-- refund_payment and fail_payment live in 0011-0012.
--
-- Requirements: 16.1, 15.8, 25.7

-- ---------------------------------------------------------------------------
-- orders
-- ---------------------------------------------------------------------------
-- amount_php is numeric(12,2), not integer: HitPay reports decimal amounts and
-- Requirement 15.1 compares at 2-decimal-place precision, so the stored value
-- has to hold two decimals to be comparable with zero tolerance. The integer
-- products.price_php widens losslessly into it (Requirement 15.5: the compared
-- value comes from the database, never from the payload).
--
-- on delete restrict on both references: an order is a financial record, so
-- deleting a buyer or a product must not silently erase it.
--
-- currency carries no check constraint here, matching the design. Orders record
-- what was charged, and Requirement 15.2 compares the reported currency against
-- this stored value at webhook time rather than constraining it at write time.

create table public.orders (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references public.profiles(id) on delete restrict,
  product_id        uuid not null references public.products(id) on delete restrict,
  amount_php        numeric(12,2) not null check (amount_php > 0),
  currency          char(3) not null default 'PHP',
  status            order_status not null default 'pending',
  hitpay_payment_id text,
  hitpay_reference  text,
  ref_code          text,
  created_at        timestamptz not null default now(),
  paid_at           timestamptz
);

comment on column public.orders.amount_php is
  'Written by the Create_Payment_Function from products.price_php at order creation. Requirement 15.5: no part of the webhook cross-check value may come from the payload.';

-- Requirement 16.1: unique over non-null payment ids only, so many pending
-- orders may coexist before HitPay assigns an id. A plain unique constraint
-- would work in Postgres (nulls are distinct) but a partial index states the
-- intent and keeps the index off the pending rows.
create unique index orders_hitpay_payment_id_key
  on public.orders (hitpay_payment_id)
  where hitpay_payment_id is not null;

-- Supports the buyer's own order history and the enrolled-confirmation poll.
create index orders_user_idx on public.orders (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- enrollments
-- ---------------------------------------------------------------------------
-- Requirement 16.1: unique (user_id, product_id) is what makes replayed
-- fulfilment idempotent at the database level, so `on conflict do nothing` in
-- fulfil_payment is a guarantee rather than a hope.
--
-- Revoking an enrollment deletes the row (design decision), which keeps this a
-- plain constraint rather than a partial index and lets a refunded buyer
-- purchase the same product again later.
--
-- order_id is nullable with on delete set null: comp and credit enrollments
-- have no order behind them.

create table public.enrollments (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles(id) on delete cascade,
  product_id uuid not null references public.products(id) on delete restrict,
  source     enrollment_source not null,
  order_id   uuid references public.orders(id) on delete set null,
  created_at timestamptz not null default now(),
  constraint enrollments_user_product_key unique (user_id, product_id)
);

comment on constraint enrollments_user_product_key on public.enrollments is
  'Requirement 16.1. Database-level idempotency for fulfilment: at most one enrollment per user per product, however many times a webhook is replayed.';

-- ---------------------------------------------------------------------------
-- quiz_attempts
-- ---------------------------------------------------------------------------
-- score and total are computed by grade-quiz from questions.correct_key with
-- the service role; any score, total, or correctness field in the request body
-- is ignored. Requirement 17.2 preserves these rows across a refund.

create table public.quiz_attempts (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles(id) on delete cascade,
  quiz_id    uuid not null references public.quizzes(id) on delete cascade,
  score      integer not null check (score >= 0),
  total      integer not null check (total >= 0),
  answers    jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- referrals
-- ---------------------------------------------------------------------------
-- Requirement 16.1: unique order_id is the exactly-once guarantee for referral
-- attribution under webhook replay.
--
-- buyer_masked is computed once by the service role at insert time
-- (juan****@gmail.com) so buyer_user_id can be withheld from the client grant
-- entirely (migration 0009) and the referrer never receives the buyer's
-- identity. product_title is denormalised so the ledger still renders after the
-- product is unpublished and therefore invisible to the referrer's catalog read.
--
-- referrals_no_self makes the self-referral guard a database invariant, not
-- only a branch in the webhook.
--
-- amount_php allows 0 (>= 0) because a credit-mode or zero-configured reward is
-- still a valid ledger row; orders.amount_php stays strictly positive.

create table public.referrals (
  id                uuid primary key default gen_random_uuid(),
  referrer_ref_code text not null,
  referrer_user_id  uuid not null references public.profiles(id) on delete cascade,
  buyer_user_id     uuid not null references public.profiles(id) on delete cascade,
  buyer_masked      text not null,
  order_id          uuid not null unique references public.orders(id) on delete cascade,
  product_id        uuid not null references public.products(id) on delete restrict,
  product_title     text not null,
  amount_php        numeric(12,2) not null check (amount_php >= 0),
  reward_type       reward_type not null,
  status            referral_status not null default 'available',
  created_at        timestamptz not null default now(),
  paid_at           timestamptz,
  notes             text,
  constraint referrals_no_self check (referrer_user_id <> buyer_user_id)
);

comment on column public.referrals.buyer_user_id is
  'Service-role only. Withheld from the column-level select grant in migration 0009; the ledger renders buyer_masked instead.';

-- Supports the earnings dashboard: available and paid balances per referrer.
create index referrals_referrer_idx on public.referrals (referrer_user_id, status);

-- ---------------------------------------------------------------------------
-- payment_incidents
-- ---------------------------------------------------------------------------
-- Requirement 15.8: the store behind every "record for admin review" clause.
-- Retains the reported amount, reported currency, reported payment identifier,
-- the stored amount and currency, and the recording time, associated with the
-- matching order where one exists, until an admin marks it resolved.
--
-- order_id is nullable: unmatched payments and unmatched refunds have no order
-- to point at, which is precisely why they are incidents.
--
-- payload holds the webhook body for forensics and can contain payer details,
-- so this table gets zero grants and zero policies (migrations 0005 and 0009);
-- the admin portal reads it through admin-incidents, never through PostgREST.

create table public.payment_incidents (
  id                uuid primary key default gen_random_uuid(),
  kind              incident_kind not null,
  order_id          uuid references public.orders(id) on delete set null,
  hitpay_payment_id text,
  reported_amount   numeric(12,2),
  reported_currency text,
  stored_amount     numeric(12,2),
  stored_currency   char(3),
  payload           jsonb,
  resolved_at       timestamptz,
  resolved_by       uuid references public.profiles(id),
  created_at        timestamptz not null default now()
);

comment on table public.payment_incidents is
  'Requirement 15.8. Service-role only: payload may contain payer details. No anon/authenticated grant and no policy may be added.';

-- Supports the admin review list: unresolved incidents, newest first, paged at 50.
create index payment_incidents_open_idx
  on public.payment_incidents (created_at desc) where resolved_at is null;

-- ---------------------------------------------------------------------------
-- payout_requests
-- ---------------------------------------------------------------------------
-- Requirement 25.7: request-payout recomputes the available balance from
-- referrals server-side and inserts exactly one row here with the supplied
-- GCash number. amount_php > 0 so a zero-balance request cannot be recorded.
-- status is text-with-check rather than an enum because it is a workflow label
-- the admin portal owns, not a value any money path branches on.

create table public.payout_requests (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles(id) on delete cascade,
  amount_php   numeric(12,2) not null check (amount_php > 0),
  gcash_number text not null,
  status       text not null default 'requested'
               check (status in ('requested','paid','rejected')),
  created_at   timestamptz not null default now(),
  handled_at   timestamptz,
  notes        text
);

-- =======================================================================
-- 0003_functions_triggers.sql
-- =======================================================================
-- 0003_functions_triggers.sql
-- Platform v2 provisioning functions and triggers:
--   gen_ref_code()          unambiguous referral code with collision retry
--   handle_new_user()       one profiles row per auth.users row, admin bootstrap
--   on_auth_user_created    the auth.users trigger that calls it
--   mask_email()            buyer mask stored on referrals.buyer_masked
--   guard_profile_columns() + profiles_guard_columns trigger
--
-- Depends on 0001_schema_core.sql for public.profiles and
-- public.admin_bootstrap_emails.
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline
-- (migration 0005) revokes execute on every function in schema public from
-- anon and authenticated; none of the functions here needs a client grant,
-- because Postgres checks EXECUTE on a trigger function when the trigger is
-- created, not each time it fires. mask_email() is called by the service role
-- from inside fulfil_payment (migration 0011), which is SECURITY DEFINER.
--
-- Requirements: 3.1, 3.2, 3.4, 9.2, 9.3, 26.2, 7.7

-- ---------------------------------------------------------------------------
-- gen_ref_code
-- ---------------------------------------------------------------------------
-- Requirement 3.2: ref_code is unique across profiles.
-- Requirement 3.4: on collision the function generates a replacement and the
-- insert completes, so uniqueness does not depend on the constraint raising.
--
-- The alphabet omits I, O, 0 and 1 so a code survives being read aloud or
-- hand-typed. 32 symbols over 8 positions is ~1.1e12 codes, so the retry loop
-- is a correctness guarantee rather than a hot path.

create or replace function public.gen_ref_code() returns text
language plpgsql
set search_path = public, pg_temp
as $$
declare
  alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  candidate text;
begin
  loop
    candidate := '';
    for i in 1..8 loop
      candidate := candidate
        || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    end loop;
    exit when not exists (
      select 1 from public.profiles where ref_code = candidate
    );
  end loop;
  return candidate;
end $$;

comment on function public.gen_ref_code() is
  'Requirement 3.4. Generates an 8-character referral code over the unambiguous alphabet and retries until it does not collide with an existing profiles.ref_code.';

-- ---------------------------------------------------------------------------
-- handle_new_user
-- ---------------------------------------------------------------------------
-- Requirement 3.1: one profiles row per auth.users insert, by way of a trigger.
-- Requirement 3.2: email copied from auth.users, ref_code unique.
-- Requirement 26.2: is_admin is true exactly when the address is in
-- admin_bootstrap_emails, which is data rather than a list inside this body, so
-- appointing an admin before their first login is a service-role insert.
--
-- SECURITY DEFINER because the trigger fires as the auth admin role, which has
-- no privilege on public.profiles. search_path is pinned so a definer function
-- cannot be redirected at a shadowed table by the caller's search_path.
--
-- Bootstrap addresses are stored lower-case in 0001, so the comparison
-- lower-cases the incoming address rather than trusting its case.
--
-- on conflict (id) do nothing keeps a re-inserted or replayed auth row from
-- raising, which would otherwise fail the signup itself.

create or replace function public.handle_new_user() returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, email, ref_code, is_admin)
  values (
    new.id,
    new.email,
    public.gen_ref_code(),
    exists (
      select 1 from public.admin_bootstrap_emails
      where email = lower(new.email)
    )
  )
  on conflict (id) do nothing;
  return new;
end $$;

comment on function public.handle_new_user() is
  'Requirements 3.1, 3.2, 26.2. Inserts the profiles row for a new auth.users row and sets is_admin from admin_bootstrap_emails.';

-- No drop-if-exists guard here: auth.users is owned by the auth admin role, and
-- DROP TRIGGER requires ownership of the table while CREATE TRIGGER needs only
-- the TRIGGER privilege. The migration ledger applies this file once.

create trigger on_auth_user_created
after insert on auth.users
for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- mask_email
-- ---------------------------------------------------------------------------
-- Requirement 7.7: the referrer sees the buyer in masked form. The mask is
-- computed once by the service role at insert time and stored in
-- referrals.buyer_masked, so buyer_user_id can be withheld from the client
-- grant entirely (migration 0009) and the raw identity never reaches the
-- browser at all.
--
-- Shape, per the design: up to the first four characters of the local part,
-- four mask characters, then the domain -> juan****@gmail.com with U+2022
-- bullets. The bullets are produced with chr(8226) so this file stays pure
-- ASCII and cannot be corrupted by a re-encode; the value stored is the bullet
-- character itself. A local part shorter than four characters is shown in full,
-- which is the same amount of information the mask shape already implies.
--
-- Anything that is not recognisably an address (null, blank, no '@', nothing
-- before the '@', nothing after it) masks to '***' rather than to null, because
-- referrals.buyer_masked is not null.

create or replace function public.mask_email(p_email text) returns text
language plpgsql
immutable
as $$
declare
  v_input  text := btrim(coalesce(p_email, ''));
  v_at     int;
  v_local  text;
  v_domain text;
begin
  v_at := position('@' in v_input);
  if v_at < 2 then
    return '***';
  end if;

  v_local  := left(v_input, v_at - 1);
  v_domain := substr(v_input, v_at + 1);

  if v_domain = '' then
    return '***';
  end if;

  return left(v_local, 4) || repeat(chr(8226), 4) || '@' || v_domain;
end $$;

comment on function public.mask_email(text) is
  'Requirement 7.7. Buyer mask stored on referrals.buyer_masked: up to four characters of the local part, four bullet characters, then the domain.';

-- ---------------------------------------------------------------------------
-- guard_profile_columns
-- ---------------------------------------------------------------------------
-- Requirements 9.2 and 9.3 are enforced first by the column-level update grant
-- in migration 0007, which permits display_name and gcash_number only. An
-- attempt to set is_admin is rejected with "permission denied for column
-- is_admin" before any policy runs.
--
-- This trigger is defence in depth behind that grant: if the grant were ever
-- widened, a client-side update of is_admin, ref_code, referred_by, email or id
-- would still be rejected, here with SQLSTATE 42501 (insufficient_privilege) so
-- the client sees the same class of error either way.
--
-- The guard applies only when a request carries a user identity. auth.uid() is
-- null for the service role, so fulfil_payment, refund_payment and the admin
-- functions can still maintain these columns; the role check is a second
-- shortcut for the same case. Comparisons use IS DISTINCT FROM so a null-to-null
-- no-op update is not mistaken for a change.

create or replace function public.guard_profile_columns() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is not null and current_setting('role') <> 'service_role' then
    if new.is_admin    is distinct from old.is_admin
    or new.ref_code    is distinct from old.ref_code
    or new.referred_by is distinct from old.referred_by
    or new.email       is distinct from old.email
    or new.id          is distinct from old.id then
      raise exception 'protected profile column' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

comment on function public.guard_profile_columns() is
  'Requirements 9.2, 9.3. Defence in depth behind the column-level update grant on profiles: blocks a user-identified update of is_admin, ref_code, referred_by, email or id.';

drop trigger if exists profiles_guard_columns on public.profiles;

create trigger profiles_guard_columns
before update on public.profiles
for each row execute function public.guard_profile_columns();

-- =======================================================================
-- 0004_settings_seed.sql
-- =======================================================================
-- 0004_settings_seed.sql
-- Platform v2 settings: the key/value configuration table and its seeded rows.
--
-- Grants and RLS are deliberately NOT in this file. The revoke-first baseline is
-- migration 0005 and the display-safe allowlist policy
-- (settings_select_display_safe) is migration 0010. This file depends only on
-- the public schema, so it is independent of 0002 and 0003.
--
-- Requirements: 20.12, 24.1, 9.9

-- ---------------------------------------------------------------------------
-- settings
-- ---------------------------------------------------------------------------
-- value is text for every key. Numeric and enumerated settings are cast at the
-- read site (fulfil_payment casts referral_amount to numeric and reward_type to
-- the reward_type enum), and per-key validation on save lives in the
-- admin-settings Edge Function. One column type keeps the admin editor and the
-- allowlist policy uniform across keys.
--
-- display_safe IS the Display_Safe_Keys allowlist from Requirement 9, expressed
-- as data rather than as a literal key list inside a policy. It defaults to
-- false, so a setting added later is private until someone deliberately marks
-- it readable: the safe direction to fail.

create table public.settings (
  key          text primary key,
  value        text not null,
  display_safe boolean not null default false,
  updated_at   timestamptz not null default now()
);

comment on table public.settings is
  'Admin-editable configuration. Client roles read only rows where display_safe = true, via settings_select_display_safe (migration 0010).';

comment on column public.settings.display_safe is
  'The Display_Safe_Keys allowlist as data. Default false: a new key is service-role only until explicitly published. answer_reveal_mode must stay false (Requirements 9.9, 6.13).';

-- ---------------------------------------------------------------------------
-- Seed
-- ---------------------------------------------------------------------------
-- Idempotent: on conflict do nothing, so re-running the migration set never
-- overwrites a value an admin has since edited through the Admin_Portal.
--
-- Requirement 24.1: referral_amount 9, reward_type cash, payout_threshold 100,
-- reward_on every_purchase. These four are display-safe because the front end
-- renders them - the referral amount on the product page, the threshold on the
-- Earnings view (Requirement 25 criteria 4 and 5).
--
-- Requirement 20.12 and 9.9: answer_reveal_mode is seeded answered_only with
-- display_safe = false. It governs how much of the answer key the grading
-- function returns, so no client role may read it; the Grade_Quiz_Function
-- reads it through the service role only.
--
-- The brand, contact, banner, and hero copy keys replace the BRAND_NAME,
-- CONTACT_EMAIL_FALLBACK, HERO_HEADLINE_FALLBACK, and HERO_SUBHEAD_FALLBACK
-- constants removed from config.js, so copy is editable without a deploy. All
-- display-safe: they are rendered to anonymous visitors by definition.
-- announcement_banner seeds empty, which the front end treats as "no banner".

insert into public.settings (key, value, display_safe) values
  ('referral_amount',     '9',                    true),
  ('reward_type',         'cash',                 true),
  ('payout_threshold',    '100',                  true),
  ('reward_on',           'every_purchase',       true),
  ('answer_reveal_mode',  'answered_only',        false),
  ('brand_name',          'ArchPrep PH',          true),
  ('contact_email',       'rehinaneel@gmail.com', true),
  ('announcement_banner', '',                     true),
  ('hero_headline',       'Pass the Architect Licensure Exam with confidence.', true),
  ('hero_subhead',        'Focused review materials and exam-style practice quizzes for Filipino architecture graduates.', true)
on conflict (key) do nothing;

-- =======================================================================
-- 0005_rls_baseline.sql
-- =======================================================================
-- 0005_rls_baseline.sql
-- Platform v2 default-deny baseline: revoke every client privilege in the
-- public schema, stop future objects from inheriting one, and enable RLS on
-- every table.
--
-- This migration grants NOTHING back. Every deliberate client privilege is
-- added by 0006-0010:
--   0006  questions lockdown (service_role select only, no client grant ever)
--   0007  profiles select + column-level update
--   0008  catalog select (products minus material_path, quizzes, pack_quizzes)
--   0009  owner-scoped select on orders, enrollments, quiz_attempts,
--         payout_requests, referrals (column-restricted)
--   0010  settings display-safe allowlist
-- If a table or column is not named in one of those files, no client role can
-- reach it. That is the whole point of this file: a policy is powerless without
-- a grant, and a grant is powerless without a policy.
--
-- Runs after 0003, so the function revokes below also cover gen_ref_code(),
-- handle_new_user(), mask_email(), and guard_profile_columns(). Re-runnable:
-- every statement here is idempotent.
--
-- Requirements: 5.1, 5.2

-- ---------------------------------------------------------------------------
-- 1. Default privileges — close the door on objects that do not exist yet
-- ---------------------------------------------------------------------------
-- Supabase ships permissive default privileges on the public schema, so a table
-- created by a later migration would silently arrive with client privileges
-- attached. These statements flip that default to "nothing", which makes every
-- grant in 0006-0010 a deliberate, reviewable act.
--
-- ALTER DEFAULT PRIVILEGES applies only to objects created by the role that
-- runs it (FOR ROLE defaults to the current role). Migrations are applied as
-- `postgres`, which is the same role Supabase's permissive defaults are
-- attached to, so the plain form is the correct one here. An object created by
-- some other role from the dashboard is outside its reach — hence the blanket
-- revokes in section 2, which catch whatever already exists.

alter default privileges in schema public
  revoke all on tables from anon, authenticated;

alter default privileges in schema public
  revoke all on sequences from anon, authenticated;

-- Functions are the important one. A new function's EXECUTE privilege is
-- granted to PUBLIC by default, and PostgREST exposes every function in the
-- public schema as an RPC endpoint. Without this, a SECURITY DEFINER function
-- added later (fulfil_payment, which writes orders, enrollments, and referrals
-- as its owner) would be callable by `authenticated` through PUBLIC even after
-- an explicit `revoke ... from anon, authenticated`. Revoking from anon and
-- authenticated alone is not enough; PUBLIC has to go too.

alter default privileges in schema public
  revoke execute on functions from anon, authenticated;

alter default privileges in schema public
  revoke execute on functions from public;

-- Deliberately NOT touched: default privileges ON TYPES and ON SCHEMAS.
-- PUBLIC holds USAGE on types by default, and the client roles need that USAGE
-- to read and filter the enum-typed columns created in 0001 (products.type,
-- orders.status, referrals.status, and the rest). Revoking it would break the
-- published-catalog read in 0008 at the type layer, not the privilege layer,
-- which is a confusing failure for zero security gain — enum USAGE discloses
-- nothing on its own.

-- ---------------------------------------------------------------------------
-- 2. Revoke what already exists
-- ---------------------------------------------------------------------------
-- Every table from 0001, 0002, and 0004 was created under Supabase's permissive
-- defaults. This is the sweep that undoes that. It is a blanket revoke rather
-- than a per-table list on purpose: a table someone forgets to add to a list
-- stays exposed, whereas ALL TABLES cannot be forgotten.

revoke all on all tables in schema public from anon, authenticated;
revoke all on all sequences in schema public from anon, authenticated;

-- ALL FUNCTIONS covers functions, aggregates, and window functions but not
-- procedures; ALL ROUTINES covers procedures as well. Using ROUTINES means a
-- procedure added later is caught by the same sweep.
--
-- PUBLIC is included for the reason given in section 1. This does not disturb
-- the trigger functions from 0003: EXECUTE on a trigger function is checked
-- when the trigger is CREATED, not each time it fires, so revoking EXECUTE
-- from the client roles leaves on_auth_user_created and
-- profiles_guard_columns working exactly as before. Those functions are never
-- called directly by a client role, which is why revoking is not merely safe
-- but correct — a client-callable path into handle_new_user() or
-- guard_profile_columns() would be a hole, not a feature.
--
-- Function bodies are unaffected too: a SECURITY DEFINER function runs as its
-- owner, and an owner keeps its privileges regardless of what PUBLIC holds, so
-- mask_email() stays callable from inside fulfil_payment().

revoke all on all routines in schema public from anon, authenticated;
revoke all on all routines in schema public from public;

-- ---------------------------------------------------------------------------
-- 3. USAGE on schema public is RETAINED
-- ---------------------------------------------------------------------------
-- No revoke of `usage on schema public` from anon or authenticated, and this is
-- deliberate. Schema USAGE is a prerequisite for exercising any privilege on an
-- object inside that schema, so dropping it would break the published-catalog
-- read (0008) and every owner-scoped read (0007, 0009, 0010) that the front end
-- depends on, and PostgREST itself needs it to resolve names for the roles it
-- switches into.
--
-- Retaining USAGE costs nothing here. USAGE alone confers no ability to read,
-- write, or even confirm the contents of a single row — it only permits name
-- resolution. With sections 1 and 2 applied, a client role holds schema USAGE
-- and zero object privileges, which is exactly the intended baseline: the door
-- to the building is open, every room inside is locked.

-- ---------------------------------------------------------------------------
-- 4. Enable RLS on every table — all 13, no exceptions
-- ---------------------------------------------------------------------------
-- Including the tables that will never get a client policy (questions,
-- payment_incidents, admin_bootstrap_emails). Enabling RLS on a table with no
-- policies is the strongest state available: zero rows for a select, a
-- policy-violation error for a write (Requirement 5.3). Leaving RLS off on a
-- service-role-only table would mean a single accidental future grant exposes
-- the whole table.

alter table public.profiles                enable row level security;
alter table public.admin_bootstrap_emails  enable row level security;
alter table public.products                enable row level security;
alter table public.quizzes                 enable row level security;
alter table public.pack_quizzes            enable row level security;
alter table public.questions               enable row level security;
alter table public.orders                  enable row level security;
alter table public.enrollments             enable row level security;
alter table public.quiz_attempts           enable row level security;
alter table public.referrals               enable row level security;
alter table public.payment_incidents       enable row level security;
alter table public.payout_requests         enable row level security;
alter table public.settings                enable row level security;

-- ---------------------------------------------------------------------------
-- 5. Force RLS on the four tables that carry identity, money, and access
-- ---------------------------------------------------------------------------
-- A table owner normally bypasses RLS. FORCE ROW LEVEL SECURITY removes that
-- exemption, so the owner is filtered by the same policies as everyone else.
-- Applied to the tables where an owner-privileged query that quietly ignored
-- the row filter would be worst: profiles (identity and is_admin), orders and
-- enrollments (money and access), referrals (rewards).
--
-- Roles holding the BYPASSRLS attribute are unaffected by FORCE — that is how
-- the Edge Functions keep working. `service_role` has BYPASSRLS, so the
-- webhook's writes to orders, enrollments, and referrals proceed, and
-- fulfil_payment runs as its owner `postgres`, which also holds BYPASSRLS on
-- Supabase. Verify both on first apply with:
--   select rolname, rolbypassrls from pg_roles
--    where rolname in ('postgres', 'service_role');
-- If either came back false, fulfil_payment's writes would fail closed against
-- zero policies rather than fail open, but the webhook would stop fulfilling
-- payments, so this is a deploy-time check worth doing once.

alter table public.profiles     force row level security;
alter table public.orders       force row level security;
alter table public.enrollments  force row level security;
alter table public.referrals    force row level security;

-- =======================================================================
-- 0006_rls_questions.sql
-- =======================================================================
-- 0006_rls_questions.sql
-- The answer-key guarantee, stated in full.
--
-- public.questions holds correct_key and explanation — the Answer_Fields. This
-- file is the auditable statement that no browser-reachable role can read them:
--   * zero grants to anon, to authenticated, and to PUBLIC
--   * zero RLS policies (RLS itself was enabled in 0005)
--   * select granted to service_role only
--
-- That combination is stronger than a filtered policy. Postgres checks table
-- privileges BEFORE it consults RLS, so a client request never reaches a row
-- filter that could be wrong: `quizzes?select=*,questions(*)` through PostgREST,
-- a select of correct_key alone, an aggregate over explanation, an order-by on
-- either column — all fail at the privilege layer, for every session state,
-- including a session belonging to a user who legitimately owns the quiz
-- (Requirements 6.2, 6.3, 6.4, 6.5, 6.9).
--
-- DO NOT, IN ANY FUTURE MIGRATION:
--   1. grant any privilege on public.questions to anon, authenticated, or
--      PUBLIC — not even a column-level grant on question_text or options.
--      Question content reaches the browser only through get-quiz, which strips
--      the Answer_Fields server-side (Requirement 6.7).
--   2. create any RLS policy on public.questions. A policy is useless without a
--      grant, so a policy here can only be a step towards adding one. There is
--      no legitimate reason for either.
--   3. create a client-callable SECURITY DEFINER function, procedure, or view
--      that reads public.questions. A definer routine runs with its owner's
--      privileges, which is precisely the hole this file exists to prevent: it
--      would hand a client role the read that the missing grant denies. Every
--      routine that touches this table must be callable by service_role only
--      (`revoke all on function ... from anon, authenticated, public`), and any
--      view over it must be created `with (security_invoker = true)` so the
--      caller's own (absent) privileges apply.
--
-- Requirement 6.6: the Answer_Fields are read through the Service_Role inside
-- the get-quiz and grade-quiz Edge Functions only. The grant below is what
-- makes those two paths work and is the complete set of read paths that exist.
-- admin-questions writes the table through the same role.
--
-- Requirements: 6.1, 6.6
-- Declared in design.md "Policy inventory": questions — client policies: none,
-- client grants: none. The test for Requirement 5.4 asserts exactly that.
-- Re-runnable: every statement is idempotent.

-- ---------------------------------------------------------------------------
-- 1. Zero client privileges
-- ---------------------------------------------------------------------------
-- 0005 already swept every table in the schema with a blanket revoke. This
-- repeats it for this one table on purpose: the guarantee should be readable in
-- one file rather than inferred from a wildcard three migrations back, and a
-- privilege granted out-of-band (a dashboard session, a hotfix) is removed
-- again the next time the migration set is applied to a fresh database.
--
-- PUBLIC is named explicitly because a grant to PUBLIC is inherited by every
-- role, so revoking from anon and authenticated alone would not close it.

revoke all on public.questions from anon, authenticated;
revoke all on public.questions from public;

-- ---------------------------------------------------------------------------
-- 2. service_role only
-- ---------------------------------------------------------------------------
-- The read path for get-quiz and grade-quiz (Requirement 6.6).

grant select on public.questions to service_role;

-- Writes for admin-questions (Requirement 8.5). Supabase's default privileges
-- already give service_role full access to tables in the public schema; naming
-- the write privileges here means the admin path does not depend on that
-- default surviving, and it keeps every privilege this table has in one place.
-- service_role is never exposed to a browser — it lives in Edge Function
-- secrets — so this widens nothing that section 1 closed.

grant insert, update, delete on public.questions to service_role;

-- ---------------------------------------------------------------------------
-- 3. The prohibition, recorded on the objects themselves
-- ---------------------------------------------------------------------------
-- 0001 set a table comment pointing here; this replaces it with the full rule,
-- so anyone who inspects the table from psql or the dashboard sees the
-- constraint before they consider adding a policy.

comment on table public.questions is
  'Answer keys (correct_key, explanation). Readable by service_role only, through the get-quiz and grade-quiz Edge Functions. NEVER add a grant to anon/authenticated/PUBLIC, NEVER add an RLS policy, and NEVER add a client-callable SECURITY DEFINER routine or non-security_invoker view over this table. See migration 0006_rls_questions.sql.';

comment on column public.questions.correct_key is
  'Answer_Field. Omitted from every get-quiz payload (Requirement 6.7) and revealed by grade-quiz only per answer_reveal_mode (Requirements 6.10, 6.12). Never selectable by a client role.';

comment on column public.questions.explanation is
  'Answer_Field. Same exposure rules as correct_key: service_role reads it, grade-quiz decides whether it is revealed, and no client role may select it.';

-- ---------------------------------------------------------------------------
-- 4. Fail-closed self-check
-- ---------------------------------------------------------------------------
-- Asserts the two claims this file makes, at apply time, against the live
-- catalog: zero policies on the table, and zero table-level or column-level
-- privileges held by anon, authenticated, or PUBLIC. If a policy or grant was
-- added out-of-band and somehow survived section 1, the migration aborts rather
-- than reporting success over a weakened model.
--
-- This is a point-in-time assertion: it sees only what exists when it runs, and
-- on a fresh apply that is migrations 0001-0005. The enduring check is the
-- policy-enumeration test for Requirement 5.4, which runs against the deployed
-- database and compares every live policy and grant to the declared inventory.
-- The two are complementary, not redundant — this one fails the deploy, that
-- one fails the build.

do $$
declare
  v_policies       integer;
  v_table_grants   integer;
  v_column_grants  integer;
  v_client_roles   text[] := array['anon', 'authenticated'];
begin
  select count(*) into v_policies
    from pg_policies
   where schemaname = 'public'
     and tablename  = 'questions';

  if v_policies > 0 then
    raise exception
      'questions lockdown violated: % RLS policy(ies) exist on public.questions. Requirement 6.1 allows zero.',
      v_policies;
  end if;

  -- grantee 0 in an aclitem is PUBLIC.
  select count(*) into v_table_grants
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    cross join lateral aclexplode(c.relacl) a
   where n.nspname = 'public'
     and c.relname = 'questions'
     and (a.grantee = 0 or a.grantee::regrole::text = any (v_client_roles));

  select count(*) into v_column_grants
    from pg_attribute att
    join pg_class c     on c.oid = att.attrelid
    join pg_namespace n on n.oid = c.relnamespace
    cross join lateral aclexplode(att.attacl) a
   where n.nspname = 'public'
     and c.relname = 'questions'
     and att.attnum > 0
     and not att.attisdropped
     and (a.grantee = 0 or a.grantee::regrole::text = any (v_client_roles));

  if v_table_grants > 0 or v_column_grants > 0 then
    raise exception
      'questions lockdown violated: % table privilege(s) and % column privilege(s) held by anon/authenticated/PUBLIC on public.questions. Requirement 6.1 allows zero.',
      v_table_grants, v_column_grants;
  end if;

  raise notice
    'questions lockdown verified: zero policies, zero client grants, select granted to service_role.';
end;
$$;

-- =======================================================================
-- 0007_rls_profiles.sql
-- =======================================================================
-- 0007_rls_profiles.sql
-- Platform v2 profiles access: own-row read, own-row update of exactly two
-- columns, and nothing else. This is the first migration after the 0005
-- baseline to grant a client privilege back, so every statement below is a
-- deliberate, reviewable widening of a default-deny table.
--
-- Declared client surface for public.profiles (design policy inventory):
--   policies : profiles_select_own, profiles_update_own
--   grants   : SELECT; UPDATE(display_name, gcash_number)
-- Nothing else. The 3.13 inventory test asserts equality against exactly that,
-- so an extra policy or a widened grant added later fails the suite.
--
-- Depends on 0001 (public.profiles), 0003 (guard_profile_columns() and the
-- profiles_guard_columns before-update trigger, the defence-in-depth layer
-- behind the column-level grant here), and 0005 (RLS enabled, FORCE RLS, and
-- every client privilege revoked). Re-runnable: the grants are idempotent and
-- each policy is dropped before it is created.
--
-- Requirements: 7.1, 9.1, 9.2, 9.3, 3.5

-- ---------------------------------------------------------------------------
-- 1. Grants — the column-level guard that Postgres actually provides
-- ---------------------------------------------------------------------------
-- Postgres has no column-level RLS, so Requirements 9.2 and 9.3 are enforced
-- with column-level GRANT, which is the mechanism designed for this job.
-- `authenticated` may write display_name and gcash_number and no other column.
--
-- UPDATE profiles SET is_admin = true WHERE id = auth.uid() is rejected with
-- "permission denied for column is_admin" at the privilege layer, before any
-- policy runs and regardless of what the row filter would have allowed.
-- ref_code, referred_by, email, and id are withheld the same way (9.3). The
-- trigger from 0003 repeats the check inside the statement so the guarantee
-- survives someone widening this grant later; it is the backstop, not the
-- primary control.
--
-- SELECT is granted on the whole table rather than a column list. Withholding
-- a column here would buy nothing: profiles_select_own restricts the reader to
-- their own row, and is_admin, ref_code, referred_by, and email on that row are
-- all values the front end legitimately renders (the account menu, the referral
-- link, the admin shell's is_admin check). Unreadable is not the requirement;
-- unwritable is, and that is what the UPDATE grant delivers.

grant select on public.profiles to authenticated;

grant update (display_name, gcash_number) on public.profiles to authenticated;

-- Deliberately NOT granted:
--   * anything at all to anon. Requirement 7.6: an unauthenticated select from
--     profiles returns zero rows, which it does at the privilege layer.
--   * INSERT. See section 3.
--   * DELETE. See section 3.

-- ---------------------------------------------------------------------------
-- 2. Policies — own row only
-- ---------------------------------------------------------------------------
-- Requirement 7.1 (read) and 9.1 (update). Both are scoped to `authenticated`,
-- so anon has no policy on this table even if a grant were ever added by
-- accident. FORCE RLS from 0005 means the table owner is filtered by these
-- policies too; service_role and postgres pass through on BYPASSRLS, which is
-- how handle_new_user() and the admin functions keep working.

drop policy if exists profiles_select_own on public.profiles;

create policy profiles_select_own on public.profiles
  for select to authenticated
  using (id = auth.uid());

-- USING filters the rows the update may target; WITH CHECK re-validates the
-- post-update row. Both are needed: without WITH CHECK a user could move their
-- own row to another id and keep it, and with the grant covering only
-- display_name and gcash_number that is already impossible, but the policy
-- should not depend on the grant to stay correct.

drop policy if exists profiles_update_own on public.profiles;

create policy profiles_update_own on public.profiles
  for update to authenticated
  using (id = auth.uid())
  with check (id = auth.uid());

-- Requirement 3.5 is satisfied by the pair above plus the column grant: the
-- Account settings view updates display_name and gcash_number on the user's own
-- row through PostgREST, with no Edge Function in the path.

-- ---------------------------------------------------------------------------
-- 3. No INSERT policy and no DELETE policy — both absences are the design
-- ---------------------------------------------------------------------------
-- NO INSERT POLICY, and no INSERT grant. A profiles row is created only by
-- handle_new_user() firing on the auth.users insert (migration 0003,
-- Requirements 3.1 and 3.2). That trigger is the single writer, which is what
-- makes "exactly one profile per user, with a unique ref_code and is_admin
-- derived from admin_bootstrap_emails" true by construction. A client-side
-- insert path would let a user create a second profile row, choose their own
-- ref_code, or set is_admin on the way in — none of which the update guard in
-- section 1 can catch, because that guard only compares an old row to a new
-- one. The absence of the insert path is therefore load-bearing, not an
-- omission.
--
-- NO DELETE POLICY, and no DELETE grant. A profiles row is removed only by
-- cascade from auth.users (profiles.id references auth.users(id) on delete
-- cascade, migration 0001), so account deletion is an auth-layer action and the
-- profile follows it. Allowing a client delete would orphan the rows that point
-- at the profile — orders, enrollments, quiz_attempts, referrals, and the
-- referred_by self-reference other profiles hold on this row's ref_code — and
-- would hand a user a way to erase their own referral attribution after a
-- purchase. Deletion belongs to auth.users alone.
--
-- Requirement 5.3 supplies the behaviour for both: with RLS enabled and no
-- policy, a client insert or delete is rejected with a policy-violation error.
-- The missing grants mean it is rejected one layer earlier still.

comment on table public.profiles is
  'Requirements 7.1, 9.1. Client surface: profiles_select_own (own row read), profiles_update_own with UPDATE granted on display_name and gcash_number only. No insert policy - rows come from handle_new_user() alone. No delete policy - rows go by cascade from auth.users alone.';

-- =======================================================================
-- 0008_rls_catalog.sql
-- =======================================================================
-- 0008_rls_catalog.sql
-- Platform v2 public catalog read: the only three tables a visitor with no
-- session may read. Runs after 0005, which revoked every client privilege in
-- the public schema and enabled RLS everywhere, so these grants and policies
-- are additive on top of a default-deny baseline.
--
-- Two halves, both required. A grant without a policy returns zero rows because
-- RLS is enabled; a policy without a grant fails at the privilege layer before
-- the row filter is consulted. The catalog is readable only because both halves
-- are present, and only for the rows and columns named here.
--
-- Requirements: 9.4, 9.5, 18.7

-- ---------------------------------------------------------------------------
-- 1. products — column-level select, material_path deliberately withheld
-- ---------------------------------------------------------------------------
-- Requirement 18.7: the browser must hold zero Storage object paths that
-- resolve without a signature. A private-bucket path resolves to nothing
-- without a signature, so exposing material_path would arguably satisfy the
-- criterion on its own — but withholding it means the browser never learns the
-- object layout at all, and the criterion becomes flatly testable as "the
-- client-visible product payload contains no material path". Materials are
-- reached one way only: issue-material-url, which checks enrollments for the
-- verified uid and mints a 300-second signed URL.
--
-- This is a column-level grant precisely so the omission is enforced by the
-- privilege layer rather than by every caller remembering to write an explicit
-- column list. `select *` from a client role returns the granted columns via
-- PostgREST; an explicit `select=material_path` is rejected with
-- `permission denied for column material_path`. Postgres has no column-level
-- RLS, so a grant is the mechanism actually designed for this.
--
-- thumbnail_path IS granted. Thumbnails live in a separate PUBLIC bucket and
-- have to render for anonymous visitors, so that path is not a secret.
--
-- Every other column in the 0001 definition is named below, including
-- created_at. Adding a column to products in a later migration does NOT widen
-- this grant — the new column stays unreadable by client roles until someone
-- adds it here on purpose, which is the behaviour we want.

grant select (
  id,
  slug,
  type,
  subject,
  title,
  subtitle,
  description,
  price_php,
  currency,
  thumbnail_path,
  includes,
  published,
  sort_order,
  created_at
) on public.products to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. quizzes and pack_quizzes — full table select
-- ---------------------------------------------------------------------------
-- Requirement 9.8: quizzes holds metadata only (slug, title, subject,
-- timer_minutes, published). Question text, correct_key, and explanation live
-- in public.questions, which carries zero client grants and zero policies, so
-- a full select grant here discloses nothing an answer key depends on.
--
-- pack_quizzes is a join table of two foreign keys and a sort order. It carries
-- no secret of its own; its rows are gated by the parent product's published
-- flag in section 3.

grant select on public.quizzes      to anon, authenticated;
grant select on public.pack_quizzes to anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Published-only select policies
-- ---------------------------------------------------------------------------
-- Requirements 9.4 and 9.5: client reads return exactly the published subset.
-- Policy names are fixed by the design's policy inventory table and are
-- asserted by the rls-policy-inventory suite; renaming one is a test failure.
--
-- SELECT only. No INSERT, UPDATE, or DELETE policy and no such grant exists on
-- any of the three tables — the catalog is written only through the admin-*
-- Edge Functions using the service role.
--
-- The drop-then-create form keeps this migration re-runnable; Postgres has no
-- `create policy if not exists`.

drop policy if exists products_select_published on public.products;

create policy products_select_published on public.products
  for select to anon, authenticated
  using (published = true);

drop policy if exists quizzes_select_published on public.quizzes;

create policy quizzes_select_published on public.quizzes
  for select to anon, authenticated
  using (published = true);

-- Requirement 9.4: pack_quizzes has no published column of its own, so
-- visibility resolves through the PARENT PRODUCT's flag. A quiz mapped only to
-- unpublished packs is therefore invisible to client roles, and unpublishing a
-- product immediately hides its mappings without touching pack_quizzes rows.
--
-- The subquery runs as the querying role, which is why it works: section 1
-- granted that role select on products.id and products.published. It is also
-- subject to products' own RLS, so products_select_published filters it a
-- second time — the predicate and the parent policy agree, which makes the
-- rule fail closed from both directions.
--
-- Qualifying the outer table as `pack_quizzes.product_id` (and aliasing the
-- inner one as `p`) keeps the correlation unambiguous; an unqualified
-- `product_id` would resolve against the subquery's table if products ever
-- gained a column by that name, silently turning the filter into a tautology.

drop policy if exists pack_quizzes_select_published on public.pack_quizzes;

create policy pack_quizzes_select_published on public.pack_quizzes
  for select to anon, authenticated
  using (exists (
    select 1
    from public.products p
    where p.id = pack_quizzes.product_id
      and p.published = true
  ));

-- =======================================================================
-- 0009_rls_owner_scoped.sql
-- =======================================================================
-- 0009_rls_owner_scoped.sql
-- Platform v2 owner-scoped reads and the service-role-only write model for the
-- money and access tables: orders, enrollments, quiz_attempts, referrals,
-- payout_requests, payment_incidents, admin_bootstrap_emails.
--
-- Depends on 0002 for the tables and on 0005 for the revoke-first baseline
-- (every client privilege in the public schema is already revoked and RLS is
-- already enabled on all 13 tables). Everything granted below is therefore
-- additive and deliberate: if a table or a column is not named in this file, no
-- client role can reach it.
--
-- The shape of this file is five SELECT grants, five own-row SELECT policies,
-- and two tables that are named only in comments because they get nothing at
-- all. There is no INSERT, UPDATE, or DELETE grant and no such policy anywhere
-- in it. Every write to these tables goes through the service role inside an
-- Edge Function (create-payment, hitpay-webhook, grade-quiz, request-payout,
-- admin-*), which is what Requirement 8 asks for.
--
-- Re-runnable: each policy is dropped first, and GRANT is idempotent.
--
-- Requirements: 7.2, 8.1, 8.5

-- ---------------------------------------------------------------------------
-- 1. orders, enrollments, quiz_attempts — read own, never write
-- ---------------------------------------------------------------------------
-- SELECT only, and only for `authenticated`. `anon` gets nothing on any of the
-- three, so an unauthenticated read fails at the privilege layer before RLS is
-- consulted (Requirement 7.6). auth.uid() is null for anon anyway, so the row
-- filter would return zero rows even if the grant existed — withholding the
-- grant means the answer is "no privilege", not "no matching rows".

grant select on public.orders        to authenticated;
grant select on public.enrollments   to authenticated;
grant select on public.quiz_attempts to authenticated;

-- Requirement 7.2. `user_id = auth.uid()` is the whole filter. A request that
-- asks for another user's rows (`orders?user_id=eq.<other>`) is not an error —
-- the filter is ANDed with the policy, so it returns zero rows (Requirement
-- 7.5). That is the correct behaviour: a 200 with an empty array discloses
-- nothing, not even whether the other user's row exists.

drop policy if exists orders_select_own on public.orders;
create policy orders_select_own on public.orders
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists enrollments_select_own on public.enrollments;
create policy enrollments_select_own on public.enrollments
  for select to authenticated
  using (user_id = auth.uid());

drop policy if exists quiz_attempts_select_own on public.quiz_attempts;
create policy quiz_attempts_select_own on public.quiz_attempts
  for select to authenticated
  using (user_id = auth.uid());

-- No INSERT, UPDATE, or DELETE grant and no such policy on any of the three
-- (Requirement 8.1). Both halves matter and neither is redundant:
--   * no grant  -> the statement is rejected with "permission denied for table"
--   * no policy -> even if a grant were added later, the write is still
--                  rejected with a policy-violation error (Requirements 8.2,
--                  8.3), because RLS is enabled with zero permissive policies
--                  for the operation.
-- Writes come from: orders and enrollments via create-payment and
-- hitpay-webhook (service role, Requirement 8.4), quiz_attempts via grade-quiz
-- only — the client never inserts an attempt, so a client cannot fabricate a
-- score.
--
-- Deliberately absent: an `enrollments` insert policy of the shape
-- `with check (user_id = auth.uid())`. It looks safe and is not. It would let
-- any logged-in user grant themselves access to any product for free, which is
-- exactly the attack Requirement 8.6 tests for. Do not add it.

-- ---------------------------------------------------------------------------
-- 2. referrals — read own, buyer identity withheld at the grant
-- ---------------------------------------------------------------------------
-- A column-level grant naming 12 of the table's 14 columns. The two withheld
-- are `buyer_user_id` and `referrer_user_id`.
--
-- `buyer_user_id` is withheld because the referrer has no business learning who
-- bought through their link. The ledger renders `buyer_masked`
-- (juan****@gmail.com), computed once by the service role at insert time, so
-- the front end has nothing to display beyond it and nothing to leak.
--
-- `referrer_user_id` is withheld because it is the referrer's own id, already
-- known to them from their session, so granting it buys nothing while widening
-- the surface.
--
-- Column-level GRANT rather than a view: PostgREST honours column privileges
-- directly, so `referrals?select=buyer_user_id` is rejected with "permission
-- denied for column buyer_user_id" and `select=*` expands to the granted
-- columns only. A view would need its own grant, its own RLS consideration, and
-- would still leave the base table one grant away from exposure.

grant select (id, referrer_ref_code, order_id, product_id, product_title,
              amount_php, reward_type, status, created_at, paid_at,
              buyer_masked, notes)
  on public.referrals to authenticated;

-- Requirement 7.2 for referrals: the owner is the REFERRER, not the buyer, so
-- the filter is `referrer_user_id = auth.uid()` rather than `user_id`.
--
-- This looks wrong at first read and is not: the USING clause references
-- `referrer_user_id`, a column the role has NO select privilege on. That is
-- legal and intended. Column privileges govern what a query may return;
-- an RLS policy expression is evaluated by the system as part of the row
-- filter, not as part of the user's select list, so it may read any column of
-- the table. The row filter therefore works while the column itself stays
-- unreadable. Removing `referrer_user_id` from the policy to "match the grant"
-- would break owner scoping entirely — leave it.

drop policy if exists referrals_select_own on public.referrals;
create policy referrals_select_own on public.referrals
  for select to authenticated
  using (referrer_user_id = auth.uid());

-- No write grant and no write policy on referrals (Requirement 8.1). Rows are
-- inserted by fulfil_payment inside the webhook transaction and updated by
-- admin-* functions when a payout is marked paid.

-- ---------------------------------------------------------------------------
-- 3. payout_requests — read own status, request through the Edge Function
-- ---------------------------------------------------------------------------
-- A user may watch their own payout requests move from requested to paid or
-- rejected, and may not create one. `request-payout` recomputes the eligible
-- balance from `referrals` server-side before inserting, so a client cannot
-- request more than it has earned; a client-side insert grant would make that
-- recomputation bypassable and the amount client-supplied.

grant select on public.payout_requests to authenticated;

drop policy if exists payout_requests_select_own on public.payout_requests;
create policy payout_requests_select_own on public.payout_requests
  for select to authenticated
  using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- 4. payment_incidents — zero grants, zero policies, stated explicitly
-- ---------------------------------------------------------------------------
-- There are no statements for this table below, and the absence is the point.
-- An absence is invisible to a reviewer, so it is written down here instead:
--
--   payment_incidents: ZERO grants to anon, ZERO grants to authenticated,
--   ZERO policies. Service role only.
--
-- `payload` holds the raw HitPay webhook body for forensics and can contain
-- payer details, so no client role may reach this table by any route. RLS is
-- already enabled on it by 0005, so the state is the strongest available: zero
-- rows for a select, a policy-violation error for a write. The admin portal
-- reads incidents through the `admin-incidents` Edge Function, never through
-- PostgREST.
--
-- The revoke below is a no-op after 0005's blanket sweep. It is kept anyway so
-- this file states the intent for the table it is responsible for, and so the
-- intent survives someone granting a privilege from the dashboard between
-- migrations. Do not replace it with a grant.

revoke all on public.payment_incidents from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 5. admin_bootstrap_emails — zero grants, zero policies, stated explicitly
-- ---------------------------------------------------------------------------
--   admin_bootstrap_emails: ZERO grants to anon, ZERO grants to authenticated,
--   ZERO policies. Service role only.
--
-- The table holds the owner email addresses that `handle_new_user()` checks to
-- set `is_admin` at signup. It is read by that trigger function, which runs as
-- its owner and therefore needs no client privilege, and it is edited by an
-- admin function. Exposing it to a client role would publish the owners' email
-- addresses and hand an attacker the exact list of addresses worth taking over.

revoke all on public.admin_bootstrap_emails from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 6. What this file deliberately does not do
-- ---------------------------------------------------------------------------
-- Requirement 8.5 covers products, pack_quizzes, quizzes, questions, and
-- settings: zero client insert, update, and delete policies, written through
-- admin functions with the service role. Their SELECT grants and policies live
-- in 0006 (questions: none at all), 0008 (catalog), and 0010 (settings); none
-- of those files issues a write grant either, and this file adds none on their
-- behalf. The declared client-privilege set across 0006-0010 is exactly the
-- policy inventory table in the design, and the inventory test in task 3.13
-- asserts equality against it — so a convenience policy added here later fails
-- that test even when every functional test still passes.
--
-- Policies declared by this file, for that test:
--   orders          orders_select_own           SELECT
--   enrollments     enrollments_select_own      SELECT
--   quiz_attempts   quiz_attempts_select_own    SELECT
--   referrals       referrals_select_own        SELECT on 12 named columns
--   payout_requests payout_requests_select_own  SELECT
--   payment_incidents        none               none
--   admin_bootstrap_emails   none               none

-- =======================================================================
-- 0010_rls_settings.sql
-- =======================================================================
-- 0010_rls_settings.sql
-- Platform v2 settings allowlist: the one client privilege on public.settings.
--
-- Depends on 0004 (creates the table and seeds the ten rows) and 0005 (revokes
-- every client privilege in the public schema and enables RLS on settings).
-- After 0005, settings is reachable by no client role at all; this file hands
-- back exactly one capability — read the rows an admin has marked display-safe.
--
-- Read-only by design. There is no insert, update, or delete grant and no such
-- policy, so the only write path to settings is the admin-settings Edge
-- Function running as the service role, which also carries the per-key
-- validation (accepting cash/credit for reward_type and
-- answered_only/full_reveal for answer_reveal_mode).
--
-- Re-runnable: the grant is idempotent by nature and the policy is dropped
-- before it is created.
--
-- Requirements: 9.6, 9.7, 6.13

-- ---------------------------------------------------------------------------
-- 1. Grant
-- ---------------------------------------------------------------------------
-- A whole-table select grant rather than a column list. Unlike products, where
-- material_path is withheld (0008), and referrals, where the buyer and referrer
-- identifiers are withheld (0009), settings has no column worth hiding from a
-- row the role is already allowed to see: key, value, display_safe, and
-- updated_at are all safe once the row itself is public. Withholding
-- display_safe in particular would buy nothing, since every visible row has it
-- true by definition of the policy below.
--
-- The grant alone discloses nothing. With RLS enabled and no policy, the select
-- privilege returns zero rows; the privilege and the policy have to agree
-- before a single row is visible.

grant select on public.settings to anon, authenticated;

-- Belt and braces on the absence of a write path. 0005 already revoked these,
-- so this changes nothing today — it states the intent in the file a reader
-- will open when they ask "can a client write a setting?", and it survives a
-- later accidental blanket grant in the schema.

revoke insert, update, delete, truncate, references, trigger
  on public.settings from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. The allowlist policy
-- ---------------------------------------------------------------------------
-- Requirement 9.6 asks for a select policy permitting rows whose key is a
-- member of Display_Safe_Keys, and 9.7 requires zero rows for anything outside
-- that set. The allowlist lives in the data as settings.display_safe (0004),
-- not as a literal key list inside this policy, for two reasons: an admin can
-- publish or unpublish a key without a migration, and a key added later
-- defaults to false, so a new setting is service-role only until someone
-- deliberately publishes it. A hard-coded list would instead have to be edited
-- in lockstep with every key change, and a forgotten edit fails open.
--
-- Requirement 6.13: answer_reveal_mode is seeded display_safe = false, so
-- settings?key=eq.answer_reveal_mode returns zero rows to anon and to
-- authenticated. That setting decides how much of the answer key grade-quiz
-- returns, and grade-quiz reads it through the service role, which is not
-- subject to this policy. Nothing in the database forces that row to stay
-- false — the admin-settings function is what refuses to publish it — but the
-- policy needs no exception for it, and the inventory test (task 3.13) plus the
-- settings allowlist property test (task 3.12) are what keep it honest.
--
-- FOR SELECT only. No `for all`, which would silently create an insert,
-- update, and delete policy too; harmless while the write grants are absent,
-- but it would turn one future careless grant into a write path.
--
-- USING (display_safe = true) is written against the boolean rather than as a
-- bare `using (display_safe)` so a null could never be mistaken for true. The
-- column is NOT NULL, so this is style, not a live hazard.

drop policy if exists settings_select_display_safe on public.settings;

create policy settings_select_display_safe on public.settings
  for select to anon, authenticated
  using (display_safe = true);

comment on policy settings_select_display_safe on public.settings is
  'Requirements 9.6, 9.7, 6.13. Client roles read only rows marked display_safe. answer_reveal_mode is seeded false, so it returns zero rows to every client role.';

-- =======================================================================
-- 0011_fn_fulfil_payment.sql
-- =======================================================================
-- 0011_fn_fulfil_payment.sql
-- Platform v2 fulfilment: public.fulfil_payment(text, numeric, text, jsonb).
--
-- The whole pay -> enrol -> attribute decision lives in ONE function body so it
-- is ONE transaction (Requirement 16.2). supabase-js issues each statement as
-- its own transaction over PostgREST, so this cannot be built correctly in
-- Deno. The hitpay-webhook Edge Function verifies the HMAC, normalises the
-- payload, and hands the entire decision to this RPC.
--
-- Depends on:
--   0001  enum types order_status, enrollment_source, referral_status,
--         reward_type, incident_kind; profiles; products
--   0002  orders (partial unique index on hitpay_payment_id), enrollments
--         (enrollments_user_product_key), referrals (unique order_id,
--         referrals_no_self), payment_incidents
--   0003  mask_email()
--   0004  settings and its seeded referral configuration
--   0005  the revoke-first baseline and FORCE RLS on orders/enrollments/
--         referrals/profiles
--
-- Privileges: SECURITY DEFINER, owned by the migration role (postgres), EXECUTE
-- granted to service_role only (Requirement 8.4). 0005 already flipped default
-- privileges to deny EXECUTE to anon, authenticated and PUBLIC for functions
-- created later, so this function arrives closed; the revokes at the bottom are
-- stated explicitly anyway, because PostgREST exposes every public-schema
-- function as an RPC endpoint and this one writes money and access rows.
--
-- RLS note: orders, enrollments and referrals are FORCE ROW LEVEL SECURITY with
-- zero policies. This body works because the owner role holds BYPASSRLS on
-- Supabase. That is the deploy-time check called out in 0005:
--   select rolname, rolbypassrls from pg_roles
--    where rolname in ('postgres', 'service_role');
-- Both must be true. If the owner lacked BYPASSRLS the writes would fail closed
-- (no silent partial fulfilment), but fulfilment would stop entirely.
--
-- search_path note: pinned to `public, pg_temp` with pg_temp LAST, so a caller
-- cannot redirect this definer function at a shadowed table, and a temp object
-- cannot shadow a public one. pg_catalog is implicitly searched first, so the
-- built-ins used here (round, upper, btrim, now) cannot be shadowed either.
-- mask_email() in 0003 has no search_path of its own, so it inherits this one
-- when called from here; the call is schema-qualified as public.mask_email so
-- resolution of the call itself cannot be diverted. Pinning search_path on
-- mask_email would be the belt-and-braces fix, but 0003 is already applied and
-- is not edited by this task.
--
-- Requirements: 15.1, 15.2, 15.3, 15.4, 15.5, 15.8, 15.9, 16.2, 16.4, 16.5,
--               16.6, 16.10, 23.1, 23.2, 23.3, 23.4, 23.5, 23.6, 23.7, 23.8,
--               24.3, 24.4, 8.4

create or replace function public.fulfil_payment(
  p_payment_id        text,
  p_reported_amount   numeric,
  p_reported_currency text,
  p_payload           jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order      public.orders;
  v_referrer   public.profiles;
  v_reported   numeric;             -- unconstrained: an absurd payload value
  v_fit        numeric(12,2);       -- must not overflow before it is judged
  v_reward_amt numeric(12,2);
  v_reward_ty  public.reward_type;
  v_reward_on  text;
  v_setting    text;
  v_mask       text;
  v_title      text;
begin
  -- (1) Resolve the order and LOCK it. The lock is what serialises overlapping
  --     duplicate deliveries (Requirement 16.6): the second call resumes only
  --     after the first commits, then re-reads the row under READ COMMITTED and
  --     sees status = 'paid'. The unique constraints still backstop it.
  --     The partial unique index on hitpay_payment_id guarantees at most one
  --     matching row (Requirement 15.1: "the single orders row").
  select * into v_order
  from public.orders
  where hitpay_payment_id = p_payment_id
  for update;

  -- (2) Unknown payment identifier (Requirements 15.7, 16.10). Zero writes to
  --     orders, enrollments and referrals; the incident is the only row added,
  --     and it commits so the webhook can answer 200.
  if not found then
    insert into public.payment_incidents
      (kind, hitpay_payment_id, reported_amount, reported_currency, payload)
    values ('unmatched_payment', p_payment_id,
            case when p_reported_amount is not null
                  and p_reported_amount <> 'NaN'::numeric
                  and abs(p_reported_amount) < 10000000000
                 then round(p_reported_amount, 2) end,
            p_reported_currency, p_payload);
    return jsonb_build_object('outcome', 'unmatched');
  end if;

  -- (3) Replay of an already-fulfilled order (Requirement 16.5). Return BEFORE
  --     touching anything, so paid_at stays exactly as the first delivery left
  --     it and the enrollment and referral rows keep every column. A blind
  --     `update ... set paid_at = now()` would satisfy the row counts and still
  --     violate 16.5.
  if v_order.status = 'paid' then
    return jsonb_build_object('outcome', 'already_paid', 'order_id', v_order.id);
  end if;

  -- (4) A completed payment reported against a refunded order is out of order
  --     (Requirement 16.9 in spirit, recorded for admin review). Leave the
  --     order, the enrollment and the referral alone.
  if v_order.status = 'refunded' then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('out_of_order_status', v_order.id, p_payment_id,
            case when p_reported_amount is not null
                  and p_reported_amount <> 'NaN'::numeric
                  and abs(p_reported_amount) < 10000000000
                 then round(p_reported_amount, 2) end,
            p_reported_currency, v_order.amount_php, v_order.currency, p_payload);
    return jsonb_build_object('outcome', 'already_refunded', 'order_id', v_order.id);
  end if;

  -- (5) Paid-amount cross-check (Requirement 15), before any enrollment row,
  --     any referral row, and any status change (15.1).
  --
  --     The comparison value is v_order.amount_php, written by create-payment
  --     from products.price_php. Zero part of it comes from the payload (15.5).
  --     Zero tolerance at two decimals, so an overpayment is a mismatch too
  --     (15.3). A null or NaN reported amount is a mismatch, which is how
  --     "absent or not parseable as a decimal number" lands here.
  --
  --     v_reported is unconstrained numeric and v_fit is the value narrowed for
  --     storage, because payment_incidents.reported_amount is numeric(12,2): an
  --     out-of-range payload amount must be recorded as a mismatch, not raise a
  --     numeric overflow that would roll back the incident and make HitPay
  --     retry a call that can never succeed. The full payload is stored either
  --     way, so nothing is lost when v_fit is null.
  v_reported := p_reported_amount;

  if v_reported is not null
     and v_reported <> 'NaN'::numeric
     and abs(v_reported) < 10000000000 then
    v_fit := round(v_reported, 2);
  else
    v_fit := null;
  end if;

  if v_reported is null
     or v_reported = 'NaN'::numeric
     or round(v_reported, 2) <> round(v_order.amount_php, 2) then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('amount_mismatch', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency, p_payload);
    return jsonb_build_object('outcome', 'amount_mismatch', 'order_id', v_order.id);
  end if;

  -- Currency compared as three-letter codes, trimmed, case-insensitive
  -- (Requirement 15.2). HitPay reports lower case; orders.currency is 'PHP'.
  -- Absent currency is a mismatch (15.4). The status is still 'pending' at this
  -- point, and stays that way (15.3, 15.4).
  if p_reported_currency is null
     or upper(btrim(p_reported_currency)) <> upper(btrim(v_order.currency)) then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('currency_mismatch', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency, p_payload);
    return jsonb_build_object('outcome', 'currency_mismatch', 'order_id', v_order.id);
  end if;

  -- From here the amount and the currency both matched, so zero incident rows
  -- are recorded for this order and fulfilment proceeds (Requirement 15.9).

  -- (6) Mark paid. now() is the transaction timestamp, stored as UTC by
  --     timestamptz (Requirement 16.2).
  update public.orders
     set status  = 'paid',
         paid_at = now()
   where id = v_order.id;

  -- (7) Grant access. The unique constraint IS the idempotency mechanism rather
  --     than a prior-existence check, so it holds under overlapping calls too
  --     (Requirements 16.4, 16.6). do nothing leaves every column of an
  --     existing enrollment untouched, including a comp enrollment for the same
  --     product.
  insert into public.enrollments (user_id, product_id, source, order_id)
  values (v_order.user_id, v_order.product_id, 'purchase', v_order.id)
  on conflict (user_id, product_id) do nothing;

  -- (8) Referral attribution (Requirement 23), inside this same transaction.
  --     No ref_code on the order: zero referral rows, enrollment already
  --     granted above (Requirement 23.8).
  if v_order.ref_code is not null and btrim(v_order.ref_code) <> '' then

    -- Requirement 23.1. Trimmed lookup so stray whitespace captured with the
    -- link cannot silently cost a referrer their credit. Case is NOT folded:
    -- ref_code is generated over an upper-case alphabet and is unique, so
    -- exact-code matching is the specified behaviour.
    select * into v_referrer
    from public.profiles
    where ref_code = btrim(v_order.ref_code);

    if not found then
      -- Requirement 23.4: unknown code, zero referral rows, enrollment stands.
      null;

    elsif v_referrer.id = v_order.user_id then
      -- Requirement 23.3: self-referral. Zero referral rows (the
      -- referrals_no_self constraint would refuse one anyway) and the attempt
      -- is recorded against the order for admin review.
      insert into public.payment_incidents
        (kind, order_id, hitpay_payment_id, payload)
      values ('self_referral', v_order.id, p_payment_id, p_payload);

    else
      -- Referral configuration is read from settings with the definer's
      -- privileges (Requirement 24.3). Every read falls back to the seeded
      -- default when the row is absent OR unusable (Requirement 24.4): a bad
      -- value must not raise, because a raise here would roll back a payment
      -- that has already been taken and make HitPay retry it forever.
      select value into v_setting from public.settings where key = 'reward_on';
      v_reward_on := lower(btrim(coalesce(v_setting, '')));
      if v_reward_on = '' then
        v_reward_on := 'every_purchase';
      end if;

      -- Requirement 23.6. The current order is already 'paid' by step 6, so it
      -- must be excluded; created_at scopes the test to a PRECEDING paid order.
      if v_reward_on = 'first_purchase_only'
         and exists (
           select 1
           from public.orders o
           where o.user_id = v_order.user_id
             and o.status  = 'paid'
             and o.id     <> v_order.id
             and o.created_at <= v_order.created_at
         ) then
        null;

      else
        -- Requirement 23.7 for 'every_purchase', and for any unrecognised
        -- reward_on value, which falls back to the seeded default behaviour.
        select value into v_setting
          from public.settings where key = 'referral_amount';
        v_setting := btrim(coalesce(v_setting, ''));
        if v_setting ~ '^[0-9]{1,10}(\.[0-9]+)?$' then
          v_reward_amt := round(v_setting::numeric, 2);
        else
          v_reward_amt := 9;                       -- seeded default (24.1, 24.4)
        end if;

        select value into v_setting
          from public.settings where key = 'reward_type';
        v_setting := lower(btrim(coalesce(v_setting, '')));
        if v_setting in ('cash', 'credit') then
          v_reward_ty := v_setting::public.reward_type;
        else
          v_reward_ty := 'cash';                   -- seeded default (24.1, 24.4)
        end if;

        -- Requirement 7.7: the buyer's identity is masked once, here, so
        -- buyer_user_id can stay outside the client grant entirely.
        v_mask := public.mask_email(
                    (select email from public.profiles where id = v_order.user_id));

        -- Denormalised so the ledger still renders after the product is
        -- unpublished. products.title is not null and the order's FK
        -- guarantees the row exists.
        select title into v_title
          from public.products where id = v_order.product_id;

        insert into public.referrals
          (referrer_ref_code, referrer_user_id, buyer_user_id, buyer_masked,
           order_id, product_id, product_title, amount_php, reward_type, status)
        values
          (v_referrer.ref_code, v_referrer.id, v_order.user_id,
           coalesce(v_mask, '***'),
           v_order.id, v_order.product_id, coalesce(v_title, 'Product'),
           v_reward_amt, v_reward_ty, 'available')
        on conflict (order_id) do nothing;   -- Requirements 23.5, 16.4
      end if;
    end if;
  end if;

  return jsonb_build_object('outcome', 'fulfilled', 'order_id', v_order.id);
end $$;

comment on function public.fulfil_payment(text, numeric, text, jsonb) is
  'Requirements 15, 16, 23, 24. One transaction: lock the order, cross-check the reported amount and currency against the stored values at two decimals with zero tolerance, mark paid, grant the enrollment, attribute the referral. Replays return at the already-paid branch with paid_at untouched. Every non-fulfilment branch returns normally so the incident row commits and the webhook can answer HTTP 200; a genuine fault raises and rolls back the whole body. Service role only.';

-- ---------------------------------------------------------------------------
-- Privileges (Requirement 8.4)
-- ---------------------------------------------------------------------------
-- PUBLIC is revoked as well as anon and authenticated. A new function's EXECUTE
-- is granted to PUBLIC by default, and both client roles inherit through it, so
-- revoking the two named roles alone would leave this function callable from a
-- browser as `POST /rest/v1/rpc/fulfil_payment`. 0005 already set the default
-- privileges that close this; these statements are the explicit belt.

revoke all on function public.fulfil_payment(text, numeric, text, jsonb) from public;
revoke all on function public.fulfil_payment(text, numeric, text, jsonb) from anon;
revoke all on function public.fulfil_payment(text, numeric, text, jsonb) from authenticated;

grant execute on function public.fulfil_payment(text, numeric, text, jsonb) to service_role;

-- =======================================================================
-- 0012_fn_refund_fail_payment.sql
-- =======================================================================
-- 0012_fn_refund_fail_payment.sql
-- Platform v2 reversal and failure paths:
--   public.refund_payment(text, numeric, text, jsonb)
--   public.fail_payment(text, numeric, text, jsonb)
--
-- Both functions are the mirror image of 0011's fulfilment: one function body,
-- therefore ONE transaction, so the order status change, the enrollment
-- revocation and the referral void either all commit or all roll back
-- (Requirement 17.12). supabase-js issues each statement as its own transaction
-- over PostgREST, so this cannot be assembled correctly in Deno; the
-- hitpay-webhook Edge Function verifies the HMAC, normalises the payload, and
-- hands the whole decision to one of these RPCs.
--
-- Depends on:
--   0001  enum types order_status, referral_status, incident_kind
--   0002  orders (partial unique index on hitpay_payment_id), enrollments
--         (enrollments_user_product_key), referrals (unique order_id),
--         payment_incidents
--   0005  the revoke-first baseline and FORCE RLS on orders/enrollments/
--         referrals
--   0011  fulfil_payment, whose conventions these two follow exactly
--
-- Privileges: SECURITY DEFINER, owned by the migration role (postgres), EXECUTE
-- granted to service_role only (Requirement 8.4). 0005 already flipped default
-- privileges so these functions arrive closed to anon, authenticated and
-- PUBLIC; the revokes at the bottom are stated explicitly anyway, because
-- PostgREST exposes every public-schema function as an RPC endpoint and these
-- two delete access rows and cancel rewards.
--
-- RLS note: orders, enrollments and referrals are FORCE ROW LEVEL SECURITY with
-- zero policies, so these bodies work because the owner role holds BYPASSRLS on
-- Supabase (the deploy-time check is stated in 0005). If the owner lacked it,
-- the writes would fail closed and roll back the whole reversal rather than
-- half-applying it.
--
-- search_path note: pinned to `public, pg_temp` with pg_temp LAST, so a caller
-- cannot redirect these definer functions at a shadowed table and a temp object
-- cannot shadow a public one. pg_catalog is searched first implicitly, so the
-- built-ins used here (round, abs, concat_ws) cannot be shadowed either.
--
-- Signature note: the reported amount and currency carry defaults, because a
-- refund is accepted for ANY reported amount (Requirement 17.1) and a failure
-- reports no amount at all, so neither value is needed to make the decision.
-- They are accepted so the reported figures can be retained on an incident row
-- (Requirement 15.8) when the payment identifier matches no order. The webhook
-- may therefore call either shape by name:
--   rpc('refund_payment', { p_payment_id, p_payload })
--   rpc('refund_payment', { p_payment_id, p_reported_amount,
--                           p_reported_currency, p_payload })
--
-- Requirements: 17.1, 17.2, 17.4, 17.5, 17.7, 17.8, 17.10, 17.11, 17.12,
--               16.8, 16.9, 15.8, 8.4

-- ---------------------------------------------------------------------------
-- refund_payment
-- ---------------------------------------------------------------------------

create or replace function public.refund_payment(
  p_payment_id        text,
  p_reported_amount   numeric default null,
  p_reported_currency text    default null,
  p_payload           jsonb   default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order public.orders;
  v_round numeric;               -- unconstrained: an absurd payload value must
  v_fit   numeric(12,2);         -- not overflow before it is recorded
begin
  -- (0) Narrow the reported amount for storage BEFORE anything else. There is
  --     no amount cross-check on a refund (Requirement 17.1), so this value
  --     never influences the decision; it only has to be storable in
  --     payment_incidents.reported_amount, which is numeric(12,2). An absurd
  --     payload figure must land as a null reported amount on an incident row,
  --     not raise a numeric overflow that would roll back the incident and make
  --     HitPay retry a call that can never succeed. The full payload is stored
  --     either way, so nothing is lost when v_fit is null.
  --
  --     abs() of Infinity fails the bound, so infinities narrow to null too,
  --     and the bound is re-tested AFTER rounding because a value just under
  --     10^10 can round up past what numeric(12,2) holds.
  v_fit := null;
  if p_reported_amount is not null
     and p_reported_amount <> 'NaN'::numeric
     and abs(p_reported_amount) < 10000000000 then
    v_round := round(p_reported_amount, 2);
    if abs(v_round) < 10000000000 then
      v_fit := v_round;
    end if;
  end if;

  -- (1) Resolve the order and LOCK it. The lock is what makes repeated and
  --     concurrent refund deliveries safe (Requirement 17.7): the second call
  --     resumes only after the first commits, then re-reads the row under READ
  --     COMMITTED and sees status = 'refunded'. The partial unique index on
  --     hitpay_payment_id guarantees at most one matching row.
  select * into v_order
  from public.orders
  where hitpay_payment_id = p_payment_id
  for update;

  -- (2) Refund for an unknown payment identifier (Requirement 17.8). Zero
  --     writes to orders, enrollments and referrals; the incident is the only
  --     row added, and it commits so the webhook can answer HTTP 200. The
  --     reported amount and currency are retained on it (Requirement 15.8).
  if not found then
    insert into public.payment_incidents
      (kind, hitpay_payment_id, reported_amount, reported_currency, payload)
    values ('unmatched_refund', p_payment_id, v_fit, p_reported_currency,
            p_payload);
    return jsonb_build_object('outcome', 'unmatched_refund');
  end if;

  -- (3) Repeat delivery for an already-refunded order (Requirement 17.7).
  --     Return BEFORE touching anything: the order row, the enrollment row
  --     count for that user and product, and the referral's status AND note all
  --     have to be exactly what the first refund left behind. Re-running the
  --     referral update would satisfy the status assertion and still violate
  --     17.7, because concat_ws would append the void note a second time.
  if v_order.status = 'refunded' then
    return jsonb_build_object('outcome', 'already_refunded',
                              'order_id', v_order.id);
  end if;

  -- (4) Requirement 17.1: the status change applies for ANY reported refunded
  --     amount, partial or full, because a partial refund still reverses the
  --     purchase. There is deliberately no amount comparison here, unlike
  --     fulfilment in 0011.
  --
  --     paid_at is left exactly as it was. The order row is retained as the
  --     financial record of a purchase that happened and was then reversed
  --     (Requirement 17.2), so erasing when it was paid would destroy audit
  --     history.
  update public.orders
     set status = 'refunded'
   where id = v_order.id;

  -- (5) Revoke access (Requirement 17.2). Scoped to THIS order's user and
  --     product, never a blanket delete, so every other enrollment held by that
  --     user survives untouched. enrollments_user_product_key means this
  --     matches at most one row.
  --
  --     Scoping deliberately stops at (user_id, product_id) and does NOT also
  --     require order_id = this order: Requirement 17.13 asserts ZERO
  --     enrollments rows for that pair after the refund, and Requirement 17.3
  --     requires the 403 to hold for every later request. An enrollment for the
  --     same pair carrying a different order_id (or a null one from a comp
  --     grant) would otherwise survive and keep the content unlocked after the
  --     money was returned.
  --
  --     Zero rows deleted is not an error (Requirement 17.10): an order with no
  --     enrollment still becomes refunded and still returns HTTP 200.
  --
  --     quiz_attempts is NOT touched. Requirement 17.2 preserves the affected
  --     user's attempt history across a refund; the 403 comes from the missing
  --     enrollment, not from erased history.
  delete from public.enrollments
   where user_id    = v_order.user_id
     and product_id = v_order.product_id;

  -- (6) Void the referral (Requirements 17.4, 17.5, 17.11).
  --
  --     status and notes on the right-hand side read the OLD row, which is what
  --     lets one statement cover both cases: an 'available' reward is simply
  --     cancelled, and a reward already paid out is cancelled WITH a note
  --     saying the money has already left, appended to whatever note was there
  --     before. concat_ws skips a null note, so a first note is not prefixed
  --     with a separator.
  --
  --     paid_at is not in the SET list, so the recorded payout timestamp
  --     survives untouched (Requirement 17.5). The platform really did send
  --     that money; the row has to keep saying so even though it is now void.
  --
  --     Requirement 17.11: zero matching rows is not an error, and zero
  --     referrals rows are ever created here.
  update public.referrals
     set status = 'void',
         notes  = concat_ws(' | ', notes,
                    case when status = 'paid'
                      then 'Voided after refund; reward had already been paid out.'
                      else 'Voided after refund.' end)
   where order_id = v_order.id;

  return jsonb_build_object('outcome', 'refunded', 'order_id', v_order.id);
end $$;

comment on function public.refund_payment(text, numeric, text, jsonb) is
  'Requirement 17. One transaction: lock the order, set status refunded for any reported refunded amount, delete the enrollment for that order''s user and product, void that order''s referral preserving paid_at and appending the already-paid note. Repeat deliveries return at the already-refunded branch with the order, enrollment count, referral status and referral note untouched. An unknown payment identifier records an unmatched_refund incident and writes nothing else. Every settled branch returns normally so the incident commits and the webhook answers HTTP 200; a genuine fault raises and rolls the whole reversal back together. Service role only.';

-- ---------------------------------------------------------------------------
-- fail_payment
-- ---------------------------------------------------------------------------

create or replace function public.fail_payment(
  p_payment_id        text,
  p_reported_amount   numeric default null,
  p_reported_currency text    default null,
  p_payload           jsonb   default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order public.orders;
  v_round numeric;
  v_fit   numeric(12,2);
begin
  -- (0) Same defensive narrowing as above. A failure payload usually reports no
  --     amount at all, which narrows to null and is stored as null.
  v_fit := null;
  if p_reported_amount is not null
     and p_reported_amount <> 'NaN'::numeric
     and abs(p_reported_amount) < 10000000000 then
    v_round := round(p_reported_amount, 2);
    if abs(v_round) < 10000000000 then
      v_fit := v_round;
    end if;
  end if;

  -- (1) Resolve and LOCK, so a failure report racing a completed-payment
  --     delivery for the same identifier cannot interleave with fulfilment.
  --     Whichever call takes the lock first decides; the second re-reads the
  --     committed status and lands on the matching branch below.
  select * into v_order
  from public.orders
  where hitpay_payment_id = p_payment_id
  for update;

  -- (2) Unknown payment identifier: zero writes to orders, enrollments and
  --     referrals, one incident row, HTTP 200 (Requirement 16.10 in spirit,
  --     recorded the same way fulfilment records it).
  if not found then
    insert into public.payment_incidents
      (kind, hitpay_payment_id, reported_amount, reported_currency, payload)
    values ('unmatched_payment', p_payment_id, v_fit, p_reported_currency,
            p_payload);
    return jsonb_build_object('outcome', 'unmatched');
  end if;

  -- (3) Requirement 16.9: a failed or cancelled payment reported against an
  --     order that is already paid is out of order. The order status, the
  --     enrollment and the referral are left ENTIRELY unchanged - the status is
  --     never downgraded from paid, because that would silently strip a buyer
  --     of access on the strength of a late or misrouted event. The incident is
  --     the only row written, and it commits so the webhook answers 200.
  if v_order.status = 'paid' then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('out_of_order_status', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency,
            p_payload);
    return jsonb_build_object('outcome', 'already_paid',
                              'order_id', v_order.id);
  end if;

  -- (4) Requirement 16.9, refunded arm. Same treatment: record it, change
  --     nothing. A refunded order must not be rewritten to failed, or the
  --     reversal audit trail would be lost.
  if v_order.status = 'refunded' then
    insert into public.payment_incidents
      (kind, order_id, hitpay_payment_id, reported_amount, reported_currency,
       stored_amount, stored_currency, payload)
    values ('out_of_order_status', v_order.id, p_payment_id, v_fit,
            p_reported_currency, v_order.amount_php, v_order.currency,
            p_payload);
    return jsonb_build_object('outcome', 'already_refunded',
                              'order_id', v_order.id);
  end if;

  -- (5) Repeat delivery of the same failure. Requirement 16.9 names only paid
  --     and refunded as out of order, so a second failure report for an
  --     already-failed order is a plain replay: no incident, no write, HTTP
  --     200.
  if v_order.status = 'failed' then
    return jsonb_build_object('outcome', 'already_failed',
                              'order_id', v_order.id);
  end if;

  -- (6) Requirement 16.8: the order was pending, so it moves to failed. Zero
  --     enrollments rows and zero referrals rows are created - there is no
  --     insert in this branch at all, which is the strongest form of that
  --     guarantee. paid_at stays null, because nothing was ever paid.
  update public.orders
     set status = 'failed'
   where id = v_order.id;

  return jsonb_build_object('outcome', 'failed', 'order_id', v_order.id);
end $$;

comment on function public.fail_payment(text, numeric, text, jsonb) is
  'Requirements 16.8, 16.9. One transaction: lock the order, move a pending order to failed granting nothing, and for an order already paid or refunded change nothing at all while recording an out_of_order_status incident for admin review. A repeated failure report for an already-failed order writes nothing. An unknown payment identifier records an unmatched_payment incident. Every settled branch returns normally so the incident commits and the webhook answers HTTP 200. Service role only.';

-- ---------------------------------------------------------------------------
-- Privileges (Requirement 8.4)
-- ---------------------------------------------------------------------------
-- PUBLIC is revoked as well as anon and authenticated. A new function's EXECUTE
-- is granted to PUBLIC by default and both client roles inherit through it, so
-- revoking the two named roles alone would leave these callable from a browser
-- as `POST /rest/v1/rpc/refund_payment`. 0005 already set the default
-- privileges that close this; these statements are the explicit belt. A client
-- reaching refund_payment could delete another user's enrollment, which is why
-- it is stated rather than assumed.

revoke all on function public.refund_payment(text, numeric, text, jsonb) from public;
revoke all on function public.refund_payment(text, numeric, text, jsonb) from anon;
revoke all on function public.refund_payment(text, numeric, text, jsonb) from authenticated;

revoke all on function public.fail_payment(text, numeric, text, jsonb) from public;
revoke all on function public.fail_payment(text, numeric, text, jsonb) from anon;
revoke all on function public.fail_payment(text, numeric, text, jsonb) from authenticated;

grant execute on function public.refund_payment(text, numeric, text, jsonb) to service_role;
grant execute on function public.fail_payment(text, numeric, text, jsonb) to service_role;

-- =======================================================================
-- 0013_v2_ops.sql
-- =======================================================================
-- 0013_v2_ops.sql
-- v2 foundations (BACKEND_RULES.md §0, §11, §12): the extra settings keys,
-- small helpers the later v2 functions share, the append-only audit_log and
-- the email outbox.

-- ---------------------------------------------------------------------------
-- Settings keys (§11). Existing rows keep their values; the brand moves from
-- ArchPrep PH to ArkiPrep only where the old default is still in place.
-- ---------------------------------------------------------------------------
insert into public.settings (key, value, display_safe) values
  ('reward_hold_days',     '0',          true),
  ('ref_ttl_days',         '30',         true),
  ('exam_date',            '2027-01-25', true),
  ('quiz_attempts',        '2',          true),
  ('session_idle_min',     '30',         true),
  ('leaderboard_mode',     'public',     true),
  ('bank_bdo',             '',           true),
  ('bank_bpi',             '',           true),
  ('bank_metrobank',       '',           true),
  ('bank_unionbank',       '',           true),
  ('bank_landbank',        '',           true),
  ('bank_account_name',    'ArkiPrep',   true),
  ('bank_sla_hours',       '24',         true),
  ('order_ttl_online_min', '60',         true),
  ('order_ttl_bank_h',     '48',         true)
on conflict (key) do nothing;

update public.settings set value = 'ArkiPrep', updated_at = now()
 where key = 'brand_name' and value = 'ArchPrep PH';

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  new.updated_at := now();
  return new;
end $$;

-- Integer setting with a fallback when the row is missing or malformed.
create or replace function public.setting_int(p_key text, p_default integer)
returns integer
language sql stable
set search_path = public, pg_temp
as $$
  select coalesce(
    (select case when btrim(value) ~ '^-?[0-9]{1,9}$' then btrim(value)::integer end
       from public.settings where key = p_key),
    p_default);
$$;

-- Access for exam_date products ends when the ALE day ends in Manila.
create or replace function public.exam_date_ts() returns timestamptz
language sql stable
set search_path = public, pg_temp
as $$
  select case when btrim(value) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
              then ((btrim(value)::date + 1)::timestamp at time zone 'Asia/Manila') end
    from public.settings where key = 'exam_date';
$$;

-- ---------------------------------------------------------------------------
-- audit_log (§0.7): append-only for every role, the service role included.
-- ---------------------------------------------------------------------------
create table public.audit_log (
  id          bigserial primary key,
  at          timestamptz not null default now(),
  actor_id    uuid references public.profiles(id) on delete set null,
  actor_email text,
  area        text not null check (area in ('payments','access','content','referrals','settings','auth','system')),
  action      text not null,
  target      text,
  details     jsonb not null default '{}'::jsonb
);
create index audit_log_at_idx on public.audit_log (at desc);

create or replace function public.audit_log_append_only() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  raise exception 'audit_log is append-only' using errcode = '42501';
end $$;

create trigger audit_log_no_update before update or delete on public.audit_log
  for each row execute function public.audit_log_append_only();
create trigger audit_log_no_truncate before truncate on public.audit_log
  for each statement execute function public.audit_log_append_only();

-- p_actor null = system.
create or replace function public.write_audit(
  p_actor uuid, p_area text, p_action text, p_target text, p_details jsonb default '{}'::jsonb
) returns void
language sql
set search_path = public, pg_temp
as $$
  insert into public.audit_log (actor_id, actor_email, area, action, target, details)
  values (p_actor,
          coalesce((select email from public.profiles where id = p_actor), 'system'),
          p_area, p_action, p_target, coalesce(p_details, '{}'::jsonb));
$$;

-- ---------------------------------------------------------------------------
-- outbox (§0.6, §12): emails are queued inside the money/access transaction
-- and sent after commit by the outbox worker. E1 (login code) is sent by
-- Supabase Auth itself; A1 is the admin alert for a new bank deposit.
-- ---------------------------------------------------------------------------
create table public.outbox (
  id          uuid primary key default gen_random_uuid(),
  template    text not null check (template ~ '^(E([2-9]|1[0-2])|A1)$'),
  to_email    text not null,
  payload     jsonb not null default '{}'::jsonb,
  dedupe_key  text unique,
  status      text not null default 'pending' check (status in ('pending','sending','sent','failed')),
  attempts    integer not null default 0 check (attempts >= 0),
  last_error  text,
  send_after  timestamptz not null default now(),
  created_at  timestamptz not null default now(),
  sent_at     timestamptz
);
create index outbox_due_idx on public.outbox (send_after) where status = 'pending';

create or replace function public.enqueue_email(
  p_template text, p_to text, p_payload jsonb, p_dedupe text default null
) returns void
language sql
set search_path = public, pg_temp
as $$
  insert into public.outbox (template, to_email, payload, dedupe_key)
  select p_template, p_to, coalesce(p_payload, '{}'::jsonb), p_dedupe
   where p_to is not null and btrim(p_to) <> ''
  on conflict (dedupe_key) do nothing;
$$;

-- =======================================================================
-- 0014_v2_catalog.sql
-- =======================================================================
-- 0014_v2_catalog.sql
-- v2 catalog (BACKEND_RULES.md §1, §8):
--   products  type material|quiz|mock|free, subject A|B|ALL, status
--             draft|published|unpublished, access rule per product
--   quizzes   time limit in seconds, status
--   questions versioned (lineage_id + version), topic, subject, status,
--             options as a plain text array and correct_index
-- Existing rows are transformed, not dropped.

-- The catalog policies read the columns replaced below; 0018 recreates them.
drop policy if exists products_select_published     on public.products;
drop policy if exists quizzes_select_published      on public.quizzes;
drop policy if exists pack_quizzes_select_published on public.pack_quizzes;

-- ---------------------------------------------------------------------------
-- products
-- ---------------------------------------------------------------------------
alter table public.products
  alter column type type text
  using (case type::text when 'quiz_pack' then 'quiz' else type::text end);
drop type public.product_type;
alter table public.products
  add constraint products_type_check check (type in ('material','quiz','mock','free'));

update public.products set subject = case
  when upper(coalesce(subject, '')) ~ '(^|[^A-Z])B$' then 'B'
  when upper(coalesce(subject, '')) ~ '(^|[^A-Z])A$' then 'A'
  else 'ALL' end;
alter table public.products
  alter column subject set default 'ALL',
  alter column subject set not null,
  add constraint products_subject_check check (subject in ('A','B','ALL'));

alter table public.products drop constraint products_price_php_check;
alter table public.products
  add constraint products_price_php_check
  check (price_php >= 0 and (type = 'free') = (price_php = 0));

alter table public.products
  add column status text not null default 'draft'
    check (status in ('draft','published','unpublished')),
  add column access_mode text,
  add column attempts_per_purchase integer
    check (attempts_per_purchase is null or attempts_per_purchase > 0),
  add column material_pages integer not null default 0 check (material_pages >= 0),
  add column updated_at timestamptz not null default now();

update public.products set
  status = case when published then 'published' else 'draft' end,
  access_mode = case type when 'material' then 'exam_date'
                          when 'free'     then 'unlimited'
                          else 'attempts' end,
  attempts_per_purchase = case when type in ('quiz','mock')
                               then public.setting_int('quiz_attempts', 2) end;

alter table public.products drop column published;
alter table public.products
  alter column access_mode set not null,
  add constraint products_access_mode_check
    check (access_mode in ('exam_date','attempts','unlimited')),
  add constraint products_attempts_match_check
    check ((access_mode = 'attempts') = (attempts_per_purchase is not null));

create trigger products_touch before update on public.products
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- quizzes
-- ---------------------------------------------------------------------------
alter table public.quizzes
  add column time_limit_sec integer not null default 0 check (time_limit_sec >= 0),
  add column status text not null default 'draft'
    check (status in ('draft','published','archived'));

update public.quizzes set
  time_limit_sec = timer_minutes * 60,
  status = case when published then 'published' else 'draft' end,
  subject = case
    when upper(coalesce(subject, '')) ~ '(^|[^A-Z])B$' then 'B'
    when upper(coalesce(subject, '')) ~ '(^|[^A-Z])A$' then 'A'
    else 'ALL' end;

alter table public.quizzes drop column timer_minutes, drop column published;
alter table public.quizzes
  alter column subject set default 'ALL',
  alter column subject set not null,
  add constraint quizzes_subject_check check (subject in ('A','B','ALL'));

-- ---------------------------------------------------------------------------
-- questions: editing creates a new version (same lineage_id, version + 1);
-- the old row is archived, and attempts keep pointing at the row they used.
-- ---------------------------------------------------------------------------
alter table public.questions
  add column lineage_id    uuid not null default gen_random_uuid(),
  add column version       integer not null default 1 check (version > 0),
  add column topic         text,
  add column subject       text check (subject in ('A','B')),
  add column status        text not null default 'published'
    check (status in ('draft','published','archived')),
  add column correct_index integer;

-- options were [{key, text}] with correct_key naming one key; both SET
-- expressions read the old row, so the index is taken before options flatten.
update public.questions q set
  correct_index = (select o.ord - 1
                     from jsonb_array_elements(q.options) with ordinality o(elem, ord)
                    where jsonb_typeof(o.elem) = 'object'
                      and o.elem->>'key' = q.correct_key
                    limit 1),
  options = (select coalesce(jsonb_agg(
                      case when jsonb_typeof(o.elem) = 'object' then to_jsonb(o.elem->>'text')
                           else o.elem end
                      order by o.ord), '[]'::jsonb)
               from jsonb_array_elements(q.options) with ordinality o(elem, ord))
 where jsonb_typeof(q.options) = 'array';

update public.questions
   set correct_index = ascii(upper(correct_key)) - 65
 where correct_index is null and correct_key ~ '^[A-Za-z]$';

update public.questions set options = '[]'::jsonb where jsonb_typeof(options) <> 'array';
update public.questions
   set correct_index = null, status = 'draft'
 where correct_index is null or correct_index >= jsonb_array_length(options);

update public.questions q set subject = z.subject
  from public.quizzes z
 where z.id = q.quiz_id and z.subject in ('A','B');

alter table public.questions drop column correct_key;
alter table public.questions
  drop constraint questions_quiz_id_question_number_key,
  add constraint questions_options_array_check check (jsonb_typeof(options) = 'array'),
  add constraint questions_correct_index_check
    check (correct_index is null
           or (correct_index >= 0 and correct_index < jsonb_array_length(options))),
  add constraint questions_published_needs_key_check
    check (status <> 'published' or correct_index is not null),
  add constraint questions_lineage_version_key unique (lineage_id, version);

create unique index questions_live_number_key
  on public.questions (quiz_id, question_number) where status <> 'archived';

-- =======================================================================
-- 0015_v2_identity.sql
-- =======================================================================
-- 0015_v2_identity.sql
-- v2 identity (BACKEND_RULES.md §3, §7):
--   admins    server-side allowlist by email; replaces profiles.is_admin and
--             admin_bootstrap_emails
--   profiles  required mobile (PH 09XXXXXXXXX, not OTP-verified), signup
--             completion, referral bound at signup
--   consents  terms_refund, privacy, public_leaderboard, marketing_email
--   sessions  one active session per account
--   auth_events / auth_locks  OTP send and wrong-code limits

-- ---------------------------------------------------------------------------
-- admins
-- ---------------------------------------------------------------------------
create table public.admins (
  email      text primary key check (email = lower(btrim(email))),
  added_by   uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

insert into public.admins (email)
select lower(btrim(email)) from public.admin_bootstrap_emails
union
select lower(btrim(email)) from public.profiles where is_admin
on conflict (email) do nothing;

create or replace function public.is_admin(p_uid uuid) returns boolean
language sql stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.profiles p
      join public.admins a on a.email = lower(btrim(p.email))
     where p.id = p_uid);
$$;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------
alter table public.profiles rename column gcash_number to mobile;

update public.profiles set mobile = case
    when regexp_replace(mobile, '[^0-9]', '', 'g') ~ '^(63|0)?9[0-9]{9}$'
    then '0' || right(regexp_replace(mobile, '[^0-9]', '', 'g'), 10)
  end
 where mobile is not null;

alter table public.profiles
  add constraint profiles_mobile_check check (mobile is null or mobile ~ '^09[0-9]{9}$'),
  add column signup_completed_at timestamptz,
  add column referred_by_user_id uuid references public.profiles(id) on delete set null;

update public.profiles p set referred_by_user_id = r.id
  from public.profiles r
 where r.ref_code = p.referred_by and r.id <> p.id;

update public.profiles set signup_completed_at = created_at
 where display_name is not null and btrim(display_name) <> '' and mobile is not null;

alter table public.profiles drop column is_admin;
drop table public.admin_bootstrap_emails;

create or replace function public.handle_new_user() returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.profiles (id, email, ref_code)
  values (new.id, new.email, public.gen_ref_code())
  on conflict (id) do nothing;
  return new;
end $$;

create or replace function public.guard_profile_columns() returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.uid() is not null and current_setting('role') <> 'service_role' then
    if new.ref_code            is distinct from old.ref_code
    or new.referred_by         is distinct from old.referred_by
    or new.referred_by_user_id is distinct from old.referred_by_user_id
    or new.signup_completed_at is distinct from old.signup_completed_at
    or new.email               is distinct from old.email
    or new.id                  is distinct from old.id then
      raise exception 'protected profile column' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------------------
-- consents
-- ---------------------------------------------------------------------------
create table public.consents (
  user_id     uuid not null references public.profiles(id) on delete cascade,
  type        text not null
              check (type in ('terms_refund','privacy','public_leaderboard','marketing_email')),
  version     text not null,
  accepted_at timestamptz not null default now(),
  primary key (user_id, type, version)
);

-- ---------------------------------------------------------------------------
-- sessions: the partial unique index is what makes "one active session" hold
-- under concurrent logins.
-- ---------------------------------------------------------------------------
create table public.sessions (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles(id) on delete cascade,
  is_admin     boolean not null default false,
  created_at   timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  ended_at     timestamptz,
  ended_reason text check (ended_reason in ('logout','idle','admin','browser_closed')),
  ua           text,
  ip_city      text
);
create unique index sessions_one_active_key on public.sessions (user_id) where ended_at is null;
create index sessions_user_idx on public.sessions (user_id, created_at desc);

-- ---------------------------------------------------------------------------
-- OTP limits
-- ---------------------------------------------------------------------------
create table public.auth_events (
  id         bigserial primary key,
  kind       text not null check (kind in ('otp_send','otp_fail')),
  email      text not null,
  ip         text,
  created_at timestamptz not null default now()
);
create index auth_events_email_idx on public.auth_events (email, kind, created_at desc);
create index auth_events_ip_idx    on public.auth_events (ip, kind, created_at desc);

create table public.auth_locks (
  email        text primary key,
  locked_until timestamptz not null
);

-- =======================================================================
-- 0016_v2_learning.sql
-- =======================================================================
-- 0016_v2_learning.sql
-- v2 access and exams (BACKEND_RULES.md §2, §8):
--   enrollments  re-buyable: one ACTIVE enrollment per (user, product),
--                attempts allowed/used, expiry, status active|ended|revoked
--   attempts     server-timed attempts with a question snapshot
--   attempt_answers  autosaved answers and flags
-- quiz_attempts rows become submitted attempts (their answers are kept as
-- legacy_answers).

-- ---------------------------------------------------------------------------
-- enrollments
-- ---------------------------------------------------------------------------
alter table public.enrollments drop constraint enrollments_user_product_key;

alter table public.enrollments
  add column access_mode      text not null default 'unlimited'
    check (access_mode in ('exam_date','attempts','unlimited','fixed')),
  add column attempts_allowed integer check (attempts_allowed is null or attempts_allowed > 0),
  add column attempts_used    integer not null default 0 check (attempts_used >= 0),
  add column expires_at       timestamptz,
  add column status           text not null default 'active'
    check (status in ('active','ended','revoked')),
  add column ended_at         timestamptz,
  add column revoked_reason   text;

update public.enrollments e set
  access_mode      = p.access_mode,
  attempts_allowed = p.attempts_per_purchase,
  expires_at       = case when p.access_mode = 'exam_date' then public.exam_date_ts() end
  from public.products p
 where p.id = e.product_id;

alter table public.enrollments
  add constraint enrollments_attempts_check
    check (attempts_allowed is null or attempts_used <= attempts_allowed),
  add constraint enrollments_order_product_key unique (order_id, product_id);

create unique index enrollments_one_active_key
  on public.enrollments (user_id, product_id) where status = 'active';

-- ---------------------------------------------------------------------------
-- attempts
-- ---------------------------------------------------------------------------
create table public.attempts (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references public.profiles(id) on delete cascade,
  quiz_id        uuid not null references public.quizzes(id) on delete cascade,
  enrollment_id  uuid references public.enrollments(id) on delete set null,
  attempt_no     integer not null default 1 check (attempt_no > 0),
  status         text not null default 'in_progress' check (status in ('in_progress','submitted')),
  question_ids   uuid[] not null default '{}',
  started_at     timestamptz not null default now(),
  ends_at        timestamptz,
  submitted_at   timestamptz,
  auto_submitted boolean not null default false,
  score          integer check (score >= 0),
  total          integer check (total >= 0),
  breakdown      jsonb,
  legacy_answers jsonb
);
create unique index attempts_one_open_key on public.attempts (user_id) where status = 'in_progress';
create index attempts_user_quiz_idx on public.attempts (user_id, quiz_id, started_at desc);
create index attempts_due_idx on public.attempts (ends_at) where status = 'in_progress';
create index attempts_board_idx on public.attempts (quiz_id) where status = 'submitted';

create table public.attempt_answers (
  attempt_id  uuid not null references public.attempts(id) on delete cascade,
  question_id uuid not null references public.questions(id) on delete cascade,
  choice      integer check (choice is null or choice >= 0),
  flagged     boolean not null default false,
  updated_at  timestamptz not null default now(),
  primary key (attempt_id, question_id)
);

insert into public.attempts
  (user_id, quiz_id, status, started_at, submitted_at, score, total, legacy_answers)
select user_id, quiz_id, 'submitted', created_at, created_at, score, total, answers
  from public.quiz_attempts;

drop table public.quiz_attempts;

-- =======================================================================
-- 0017_v2_money.sql
-- =======================================================================
-- 0017_v2_money.sql
-- v2 money (BACKEND_RULES.md §4-§7, §10):
--   orders          AP-xxxxx order_no, price snapshot, coupon, referrer,
--                   access snapshot, method, PayMongo refs, expiry, new states
--   payment_events  webhook dedupe by provider_event_id
--   incidents       (was payment_incidents) + ticket numbers
--   issues          student payment reports
--   coupons / coupon_reservations  reserve -> use | release
--   bank_deposits   proof uploads and review
--   referrals       status available|redeemed|void, whole pesos
--   balance_ledger  one balance per user = sum of rows
--   payouts         (was payout_requests)
-- HitPay columns are dropped: PayMongo replaces HitPay.

-- Databases built from an earlier draft of 0002 name the HitPay columns
-- provider_payment_id / provider_reference (index orders_provider_payment_id_key).
-- Bring them to the 0002 names first so the rest of this file applies to both.
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'orders'
                and column_name = 'provider_payment_id')
     and not exists (select 1 from information_schema.columns
                      where table_schema = 'public' and table_name = 'orders'
                        and column_name = 'hitpay_payment_id') then
    alter table public.orders rename column provider_payment_id to hitpay_payment_id;
    alter table public.orders rename column provider_reference to hitpay_reference;
    alter index if exists public.orders_provider_payment_id_key rename to orders_hitpay_payment_id_key;
  end if;
  if exists (select 1 from information_schema.columns
              where table_schema = 'public' and table_name = 'payment_incidents'
                and column_name = 'provider_payment_id')
     and not exists (select 1 from information_schema.columns
                      where table_schema = 'public' and table_name = 'payment_incidents'
                        and column_name = 'hitpay_payment_id') then
    alter table public.payment_incidents rename column provider_payment_id to hitpay_payment_id;
  end if;
end $$;

-- The v1 payment functions read the columns replaced below; the v2 functions
-- (0020) replace them.
do $$
declare r record;
begin
  for r in
    select p.oid::regprocedure as sig
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public'
       and p.proname in ('fulfil_payment', 'refund_payment', 'fail_payment')
  loop
    execute format('drop function %s', r.sig);
  end loop;
end $$;

-- ---------------------------------------------------------------------------
-- coupons (before orders, which reference them)
-- ---------------------------------------------------------------------------
create table public.coupons (
  id             uuid primary key default gen_random_uuid(),
  code           text not null unique check (code = upper(btrim(code)) and code ~ '^[A-Z0-9_-]{3,32}$'),
  type           text not null check (type in ('percent','fixed')),
  value          integer not null check (value > 0 and (type <> 'percent' or value <= 100)),
  product_ids    uuid[],   -- null = every product
  usage_limit    integer check (usage_limit is null or usage_limit > 0),
  used_count     integer not null default 0 check (used_count >= 0),
  reserved_count integer not null default 0 check (reserved_count >= 0),
  starts_at      timestamptz,
  expires_at     timestamptz,
  active         boolean not null default true,
  created_by     uuid references public.profiles(id) on delete set null,
  created_at     timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- orders
-- ---------------------------------------------------------------------------
create sequence public.order_no_seq start 20001;

alter table public.orders add column order_no text;
with o as (select id, row_number() over (order by created_at, id) as rn from public.orders)
update public.orders set order_no = 'AP-' || (20000 + o.rn) from o where o.id = orders.id;
do $$ begin perform setval('public.order_no_seq', 20001 + (select count(*) from public.orders), false); end $$;
alter table public.orders
  alter column order_no set default ('AP-' || nextval('public.order_no_seq')),
  alter column order_no set not null,
  add constraint orders_order_no_key unique (order_no);

alter table public.orders alter column status drop default;
alter table public.orders
  alter column status type text
  using (case status::text when 'pending' then 'awaiting_payment' else status::text end);
drop type public.order_status;
alter table public.orders
  alter column status set default 'created',
  add constraint orders_status_check check (status in (
    'created','awaiting_payment','awaiting_proof','pending_approval',
    'on_hold','paid','failed','expired','refunded'));

alter table public.orders
  add column price_php           integer,
  add column discount_php        integer not null default 0 check (discount_php >= 0),
  add column coupon_id           uuid references public.coupons(id) on delete restrict,
  add column total_php           integer,
  add column referrer_user_id    uuid references public.profiles(id) on delete set null,
  add column access_snapshot     jsonb not null default '{}'::jsonb,
  add column method              text check (method in ('gcash','maya','qrph','bank')),
  add column provider_ref        text,
  add column provider_payment_id text,
  add column checkout_url        text,
  add column expires_at          timestamptz,
  add column terms_accepted_at   timestamptz,
  add column refunded_at         timestamptz,
  add column updated_at          timestamptz not null default now();

update public.orders o set
  price_php        = round(o.amount_php)::integer,
  total_php        = round(o.amount_php)::integer,
  provider_ref     = o.hitpay_payment_id,
  referrer_user_id = (select r.id from public.profiles r
                       where r.ref_code = o.ref_code and r.id <> o.user_id),
  access_snapshot  = (select jsonb_build_object(
                        'type', p.type, 'title', p.title, 'access_mode', p.access_mode,
                        'attempts', p.attempts_per_purchase)
                        from public.products p where p.id = o.product_id);

alter table public.orders
  drop column amount_php,
  drop column hitpay_payment_id,
  drop column hitpay_reference,
  alter column price_php set not null,
  alter column total_php set not null,
  add constraint orders_amounts_check
    check (price_php >= 0 and total_php >= 0 and total_php = price_php - discount_php);

create unique index orders_provider_ref_key on public.orders (provider_ref) where provider_ref is not null;
create unique index orders_provider_payment_id_key on public.orders (provider_payment_id)
  where provider_payment_id is not null;
create index orders_status_idx on public.orders (status, created_at);

create trigger orders_touch before update on public.orders
  for each row execute function public.touch_updated_at();

create table public.coupon_reservations (
  order_id   uuid primary key references public.orders(id) on delete cascade,
  coupon_id  uuid not null references public.coupons(id) on delete restrict,
  status     text not null default 'reserved' check (status in ('reserved','used','released')),
  updated_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- payment_events
-- ---------------------------------------------------------------------------
create table public.payment_events (
  id                uuid primary key default gen_random_uuid(),
  provider          text not null default 'paymongo',
  provider_event_id text not null unique,
  type              text not null,
  order_id          uuid references public.orders(id) on delete set null,
  payload           jsonb not null,
  outcome           text,
  received_at       timestamptz not null default now(),
  processed_at      timestamptz
);
create index payment_events_order_idx on public.payment_events (order_id);

-- ---------------------------------------------------------------------------
-- incidents (was payment_incidents) and issues share one INC-#### sequence
-- ---------------------------------------------------------------------------
create sequence public.ticket_no_seq start 401;

alter table public.payment_incidents rename to incidents;
alter table public.incidents alter column kind type text using kind::text;
drop type public.incident_kind;
alter table public.incidents
  add constraint incidents_kind_check check (kind in (
    'amount_mismatch','currency_mismatch','unmatched_payment','unmatched_refund',
    'out_of_order_status','self_referral','duplicate_payment'));
alter table public.incidents rename column hitpay_payment_id to provider_ref;
alter table public.incidents
  add column ticket_no text not null default ('INC-' || lpad(nextval('public.ticket_no_seq')::text, 4, '0')),
  add column notes text,
  add constraint incidents_ticket_no_key unique (ticket_no);

create table public.issues (
  id          uuid primary key default gen_random_uuid(),
  ticket_no   text not null unique default ('INC-' || lpad(nextval('public.ticket_no_seq')::text, 4, '0')),
  user_id     uuid not null references public.profiles(id) on delete cascade,
  order_id    uuid not null references public.orders(id) on delete cascade,
  type        text not null check (type in ('not_unlocked','duplicate','failed_but_charged')),
  details     text,
  proof_path  text,
  status      text not null default 'open' check (status in ('open','resolved','refunded','rejected')),
  resolution  text,
  resolved_by uuid references public.profiles(id) on delete set null,
  resolved_at timestamptz,
  created_at  timestamptz not null default now()
);
create index issues_status_idx on public.issues (status, created_at);

-- ---------------------------------------------------------------------------
-- bank_deposits
-- ---------------------------------------------------------------------------
create table public.bank_deposits (
  id              uuid primary key default gen_random_uuid(),
  order_id        uuid not null references public.orders(id) on delete cascade,
  user_id         uuid not null references public.profiles(id) on delete cascade,
  bank            text not null check (bank in ('bdo','bpi','metrobank','unionbank','landbank')),
  amount_received integer not null check (amount_received > 0),
  reference_no    text not null check (btrim(reference_no) <> ''),
  proof_path      text not null,
  proof_sha256    text not null check (proof_sha256 ~ '^[0-9a-f]{64}$'),
  status          text not null default 'pending_approval'
                  check (status in ('pending_approval','approved','rejected','superseded')),
  reject_reason   text,
  reviewed_by     uuid references public.profiles(id) on delete set null,
  reviewed_at     timestamptz,
  created_at      timestamptz not null default now()
);
create unique index bank_deposits_one_pending_key on public.bank_deposits (order_id)
  where status = 'pending_approval';
create index bank_deposits_ref_idx on public.bank_deposits (bank, reference_no);
create index bank_deposits_sha_idx on public.bank_deposits (proof_sha256);

-- ---------------------------------------------------------------------------
-- referrals: available | redeemed | void, whole pesos
-- ---------------------------------------------------------------------------
alter table public.referrals alter column status drop default;
alter table public.referrals
  alter column status type text
  using (case status::text when 'paid' then 'redeemed' else status::text end);
drop type public.referral_status;
alter table public.referrals
  alter column status set default 'available',
  add constraint referrals_status_check check (status in ('available','redeemed','void')),
  alter column amount_php type integer using round(amount_php)::integer;
alter table public.referrals rename column paid_at to redeemed_at;
alter table public.referrals add column voided_at timestamptz;

-- ---------------------------------------------------------------------------
-- balance_ledger and payouts
-- ---------------------------------------------------------------------------
create table public.balance_ledger (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references public.profiles(id) on delete cascade,
  amount_php integer not null check (amount_php <> 0),
  source     text not null
             check (source in ('referral','deposit_credit','payout','payout_reversal','adjustment')),
  ref_id     uuid,
  note       text,
  created_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
-- Each referral, deposit credit, payout and reversal posts at most once.
create unique index balance_ledger_once_key on public.balance_ledger (source, ref_id)
  where ref_id is not null;
create index balance_ledger_user_idx on public.balance_ledger (user_id, created_at desc);

create table public.payouts (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles(id) on delete cascade,
  amount_php   integer not null check (amount_php > 0),
  mobile       text not null,
  status       text not null default 'requested' check (status in ('requested','sent','reversed')),
  gcash_ref    text,
  requested_at timestamptz not null default now(),
  sent_at      timestamptz,
  handled_by   uuid references public.profiles(id) on delete set null,
  notes        text
);
create index payouts_status_idx on public.payouts (status, requested_at);

insert into public.payouts (id, user_id, amount_php, mobile, status, requested_at, sent_at, notes)
select id, user_id, round(amount_php)::integer, gcash_number,
       case status when 'paid' then 'sent' when 'rejected' then 'reversed' else 'requested' end,
       created_at, case when status = 'paid' then handled_at end, notes
  from public.payout_requests;

create unique index payouts_one_open_key on public.payouts (user_id) where status = 'requested';

-- Opening balances from v1 history.
insert into public.balance_ledger (user_id, amount_php, source, ref_id, created_at)
select referrer_user_id, amount_php, 'referral', id, created_at
  from public.referrals where status in ('available','redeemed') and amount_php > 0;
insert into public.balance_ledger (user_id, amount_php, source, ref_id, created_at)
select user_id, -amount_php, 'payout', id, requested_at from public.payouts;
insert into public.balance_ledger (user_id, amount_php, source, ref_id, created_at)
select user_id, amount_php, 'payout_reversal', id, requested_at
  from public.payouts where status = 'reversed';

drop table public.payout_requests;

create or replace function public.balance_of(p_uid uuid) returns integer
language sql stable
set search_path = public, pg_temp
as $$
  select coalesce(sum(amount_php), 0)::integer from public.balance_ledger where user_id = p_uid;
$$;

-- =======================================================================
-- 0018_v2_rls.sql
-- =======================================================================
-- 0018_v2_rls.sql
-- Row-Level Security for the v2 schema (BACKEND_RULES.md §13).
-- Students read only their own rows; every write goes through an Edge
-- Function (service role) or a security definer function. New tables get no
-- client grant by default (0005 default privileges), so each grant below is
-- deliberate.

-- ---------------------------------------------------------------------------
-- RLS on every new table; FORCE on the money and identity tables.
-- ---------------------------------------------------------------------------
alter table public.admins              enable row level security;
alter table public.consents            enable row level security;
alter table public.sessions            enable row level security;
alter table public.auth_events         enable row level security;
alter table public.auth_locks          enable row level security;
alter table public.attempts            enable row level security;
alter table public.attempt_answers     enable row level security;
alter table public.coupons             enable row level security;
alter table public.coupon_reservations enable row level security;
alter table public.payment_events      enable row level security;
alter table public.issues              enable row level security;
alter table public.bank_deposits       enable row level security;
alter table public.balance_ledger      enable row level security;
alter table public.payouts             enable row level security;
alter table public.audit_log           enable row level security;
alter table public.outbox              enable row level security;

alter table public.admins         force row level security;
alter table public.sessions       force row level security;
alter table public.bank_deposits  force row level security;
alter table public.balance_ledger force row level security;
alter table public.payouts        force row level security;
alter table public.audit_log      force row level security;

-- ---------------------------------------------------------------------------
-- Catalog: published rows for everyone; a student also keeps seeing a product
-- they hold an active enrollment for after it is unpublished (§1).
-- material_path stays server-only.
-- ---------------------------------------------------------------------------
revoke select on public.products from anon, authenticated;
grant select (
  id, slug, type, subject, title, subtitle, description, price_php, currency,
  thumbnail_path, includes, status, sort_order, created_at, access_mode,
  attempts_per_purchase, material_pages, updated_at
) on public.products to anon, authenticated;

create policy products_select_published on public.products
  for select to anon, authenticated
  using (status = 'published');

create policy products_select_enrolled on public.products
  for select to authenticated
  using (exists (select 1 from public.enrollments e
                  where e.product_id = products.id
                    and e.user_id = auth.uid()
                    and e.status = 'active'));

create policy quizzes_select_published on public.quizzes
  for select to anon, authenticated
  using (status = 'published');

create policy pack_quizzes_select_published on public.pack_quizzes
  for select to anon, authenticated
  using (exists (select 1 from public.products p
                  where p.id = pack_quizzes.product_id and p.status = 'published')
     and exists (select 1 from public.quizzes q
                  where q.id = pack_quizzes.quiz_id and q.status = 'published'));

-- ---------------------------------------------------------------------------
-- Profiles: the user may edit only display_name and mobile; everything else
-- goes through complete_signup() or the admin functions.
-- ---------------------------------------------------------------------------
revoke update on public.profiles from authenticated;
grant update (display_name, mobile) on public.profiles to authenticated;

-- ---------------------------------------------------------------------------
-- Owner-scoped reads
-- ---------------------------------------------------------------------------
grant select on public.attempts       to authenticated;
grant select on public.consents       to authenticated;
grant select on public.balance_ledger to authenticated;
grant select on public.payouts        to authenticated;
grant select on public.issues         to authenticated;
grant select (id, user_id, is_admin, created_at, last_seen_at, ended_at, ended_reason, ua, ip_city)
  on public.sessions to authenticated;
grant select (id, order_id, user_id, bank, amount_received, reference_no, status,
              reject_reason, reviewed_at, created_at)
  on public.bank_deposits to authenticated;
grant select (attempt_id, question_id, choice, flagged, updated_at)
  on public.attempt_answers to authenticated;
grant select (voided_at) on public.referrals to authenticated;

create policy attempts_select_own       on public.attempts       for select to authenticated using (user_id = auth.uid());
create policy consents_select_own       on public.consents       for select to authenticated using (user_id = auth.uid());
create policy balance_ledger_select_own on public.balance_ledger for select to authenticated using (user_id = auth.uid());
create policy payouts_select_own        on public.payouts        for select to authenticated using (user_id = auth.uid());
create policy issues_select_own         on public.issues         for select to authenticated using (user_id = auth.uid());
create policy sessions_select_own       on public.sessions       for select to authenticated using (user_id = auth.uid());
create policy bank_deposits_select_own  on public.bank_deposits  for select to authenticated using (user_id = auth.uid());
create policy attempt_answers_select_own on public.attempt_answers for select to authenticated
  using (exists (select 1 from public.attempts a
                  where a.id = attempt_answers.attempt_id and a.user_id = auth.uid()));

-- admins, auth_events, auth_locks, coupons, coupon_reservations,
-- payment_events, incidents, audit_log and outbox: no client grant, no policy.
-- Coupons are validated by create-payment; the code list is never readable.

-- =======================================================================
-- 0019_fn_v2_identity.sql
-- =======================================================================
-- 0019_fn_v2_identity.sql
-- Signup, OTP limits and the one-active-session rule (BACKEND_RULES.md §3, §7).
-- Every function here is service-role only: Edge Functions call them after
-- verifying the caller's token.

-- ---------------------------------------------------------------------------
-- complete_signup: first login = signup. Idempotent: a second call on a
-- completed profile is a no-op. The referral binds here, once (first touch),
-- and never to the user themselves, their email or their mobile.
-- ---------------------------------------------------------------------------
create or replace function public.complete_signup(
  p_uid          uuid,
  p_display_name text,
  p_mobile       text,
  p_consents     text[],
  p_version      text,
  p_ref_code     text default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_profile  public.profiles;
  v_referrer public.profiles;
  v_name     text := btrim(coalesce(p_display_name, ''));
  v_mobile   text := regexp_replace(coalesce(p_mobile, ''), '[^0-9]', '', 'g');
  v_type     text;
begin
  select * into v_profile from public.profiles where id = p_uid for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;
  if v_profile.signup_completed_at is not null then
    return jsonb_build_object('ok', true, 'already', true);
  end if;

  if char_length(v_name) < 2 or char_length(v_name) > 40 then
    raise exception 'DISPLAY_NAME_INVALID';
  end if;
  if v_mobile ~ '^639[0-9]{9}$' then
    v_mobile := '0' || substr(v_mobile, 3);
  end if;
  if v_mobile !~ '^09[0-9]{9}$' then
    raise exception 'MOBILE_INVALID';
  end if;
  if not (p_consents @> array['terms_refund','privacy','public_leaderboard']) then
    raise exception 'CONSENT_REQUIRED';
  end if;

  update public.profiles
     set display_name = v_name, mobile = v_mobile, signup_completed_at = now()
   where id = p_uid;

  foreach v_type in array p_consents loop
    if v_type in ('terms_refund','privacy','public_leaderboard','marketing_email') then
      insert into public.consents (user_id, type, version)
      values (p_uid, v_type, coalesce(nullif(btrim(p_version), ''), 'v1'))
      on conflict do nothing;
    end if;
  end loop;

  if v_profile.referred_by is null and nullif(btrim(coalesce(p_ref_code, '')), '') is not null then
    select * into v_referrer from public.profiles where ref_code = upper(btrim(p_ref_code));
    if found
       and v_referrer.id <> p_uid
       and lower(v_referrer.email) <> lower(v_profile.email)
       and v_referrer.mobile is distinct from v_mobile then
      update public.profiles
         set referred_by = v_referrer.ref_code, referred_by_user_id = v_referrer.id
       where id = p_uid;
    end if;
  end if;

  perform public.write_audit(p_uid, 'auth', 'signup', v_profile.email,
                             jsonb_build_object('consents', p_consents));
  return jsonb_build_object('ok', true, 'already', false);
end $$;

-- ---------------------------------------------------------------------------
-- OTP limits: resend after 60s, max 5 sends/hour per email and per IP,
-- 5 wrong codes lock the email for 15 minutes.
-- ---------------------------------------------------------------------------
create or replace function public.otp_send_check(p_email text, p_ip text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email  text := lower(btrim(p_email));
  v_locked timestamptz;
  v_last   timestamptz;
begin
  select locked_until into v_locked from public.auth_locks
   where email = v_email and locked_until > now();
  if found then
    return jsonb_build_object('ok', false, 'reason', 'locked',
      'retry_after_sec', ceil(extract(epoch from v_locked - now())));
  end if;

  select max(created_at) into v_last from public.auth_events
   where email = v_email and kind = 'otp_send';
  if v_last is not null and v_last > now() - interval '60 seconds' then
    return jsonb_build_object('ok', false, 'reason', 'too_soon',
      'retry_after_sec', ceil(extract(epoch from v_last + interval '60 seconds' - now())));
  end if;

  if (select count(*) from public.auth_events
       where email = v_email and kind = 'otp_send' and created_at > now() - interval '1 hour') >= 5
  or (p_ip is not null and
      (select count(*) from public.auth_events
        where ip = p_ip and kind = 'otp_send' and created_at > now() - interval '1 hour') >= 5) then
    return jsonb_build_object('ok', false, 'reason', 'rate_limited', 'retry_after_sec', 3600);
  end if;

  insert into public.auth_events (kind, email, ip) values ('otp_send', v_email, p_ip);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.otp_verify_allowed(p_email text) returns boolean
language sql stable
security definer
set search_path = public, pg_temp
as $$
  select not exists (select 1 from public.auth_locks
                      where email = lower(btrim(p_email)) and locked_until > now());
$$;

create or replace function public.otp_record_failure(p_email text, p_ip text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text := lower(btrim(p_email));
  v_fails integer;
begin
  insert into public.auth_events (kind, email, ip) values ('otp_fail', v_email, p_ip);
  select count(*) into v_fails from public.auth_events
   where email = v_email and kind = 'otp_fail' and created_at > now() - interval '15 minutes';
  if v_fails >= 5 then
    insert into public.auth_locks (email, locked_until)
    values (v_email, now() + interval '15 minutes')
    on conflict (email) do update set locked_until = excluded.locked_until;
    return jsonb_build_object('locked', true);
  end if;
  return jsonb_build_object('locked', false, 'remaining', 5 - v_fails);
end $$;

create or replace function public.otp_record_success(p_email text) returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  delete from public.auth_events where email = lower(btrim(p_email)) and kind = 'otp_fail';
$$;

-- ---------------------------------------------------------------------------
-- Sessions. Students idle out after session_idle_min (30), admins after 8h.
-- ---------------------------------------------------------------------------
create or replace function public.session_idle_limit(p_is_admin boolean) returns interval
language sql stable
set search_path = public, pg_temp
as $$
  select case when p_is_admin then interval '8 hours'
              else public.setting_int('session_idle_min', 30) * interval '1 minute' end;
$$;

create or replace function public.start_session(
  p_uid uuid, p_is_admin boolean, p_ua text, p_ip_city text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_other public.sessions;
  v_id    uuid;
begin
  update public.sessions
     set ended_at = now(), ended_reason = 'idle'
   where user_id = p_uid and ended_at is null
     and last_seen_at < now() - public.session_idle_limit(is_admin);

  select * into v_other from public.sessions where user_id = p_uid and ended_at is null;
  if found then
    return jsonb_build_object('ok', false, 'code', 'SESSION_ACTIVE',
      'other', jsonb_build_object('ua', v_other.ua, 'ip_city', v_other.ip_city,
                                  'last_seen_at', v_other.last_seen_at,
                                  'created_at', v_other.created_at));
  end if;

  begin
    insert into public.sessions (user_id, is_admin, ua, ip_city)
    values (p_uid, coalesce(p_is_admin, false), left(p_ua, 300), left(p_ip_city, 100))
    returning id into v_id;
  exception when unique_violation then
    return jsonb_build_object('ok', false, 'code', 'SESSION_ACTIVE');
  end;
  return jsonb_build_object('ok', true, 'session_id', v_id);
end $$;

-- Heartbeat and per-request check. Returns false when the session is gone,
-- idle or belongs to someone else; an idle session is ended on the way.
create or replace function public.touch_session(p_uid uuid, p_session_id uuid) returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_s public.sessions;
begin
  select * into v_s from public.sessions
   where id = p_session_id and user_id = p_uid and ended_at is null
   for update;
  if not found then
    return false;
  end if;
  if v_s.last_seen_at < now() - public.session_idle_limit(v_s.is_admin) then
    update public.sessions set ended_at = now(), ended_reason = 'idle' where id = v_s.id;
    return false;
  end if;
  update public.sessions set last_seen_at = now() where id = v_s.id;
  return true;
end $$;

-- p_actor = the user (logout) or an admin (End session: audited + email E9).
create or replace function public.end_session(
  p_session_id uuid, p_actor uuid, p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_s     public.sessions;
  v_email text;
begin
  update public.sessions set ended_at = now(), ended_reason = p_reason
   where id = p_session_id and ended_at is null
  returning * into v_s;
  if not found then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  if p_reason = 'admin' then
    select email into v_email from public.profiles where id = v_s.user_id;
    perform public.write_audit(p_actor, 'access', 'session_ended', v_email,
                               jsonb_build_object('session_id', v_s.id, 'ua', v_s.ua));
    perform public.enqueue_email('E9', v_email,
      jsonb_build_object('name', (select display_name from public.profiles where id = v_s.user_id)),
      'E9:' || v_s.id);
  end if;
  return jsonb_build_object('ok', true, 'noop', false);
end $$;

create or replace function public.end_stale_sessions() returns integer
language sql
security definer
set search_path = public, pg_temp
as $$
  with ended as (
    update public.sessions set ended_at = now(), ended_reason = 'idle'
     where ended_at is null and last_seen_at < now() - public.session_idle_limit(is_admin)
    returning 1)
  select count(*)::integer from ended;
$$;

-- =======================================================================
-- 0020_fn_v2_orders.sql
-- =======================================================================
-- 0020_fn_v2_orders.sql
-- Orders, PayMongo events, bank deposits, refunds and admin access changes
-- (BACKEND_RULES.md §2, §4, §5, §6, §7, §10). Each function is one
-- transaction; status guards (WHERE status = 'expected') make retries,
-- double clicks, duplicate webhooks and two admins harmless. Errors raise a
-- short code (ALREADY_OWNED, COUPON_UNAVAILABLE, ...) that the Edge Function
-- maps to an HTTP response. fulfil_order is the only place that grants
-- access for an order.

-- ---------------------------------------------------------------------------
-- Small helpers
-- ---------------------------------------------------------------------------
-- An active enrollment past its expiry or out of attempts no longer counts
-- as owned; end it so the partial unique index frees up for a re-buy.
create or replace function public.end_lapsed_enrollments(p_uid uuid, p_product_id uuid)
returns void
language sql
set search_path = public, pg_temp
as $$
  update public.enrollments
     set status = 'ended', ended_at = now()
   where user_id = p_uid and product_id = p_product_id and status = 'active'
     and ((expires_at is not null and expires_at <= now())
       or (attempts_allowed is not null and attempts_used >= attempts_allowed));
$$;

create or replace function public.release_coupon(p_order_id uuid) returns void
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_coupon uuid;
begin
  update public.coupon_reservations
     set status = 'released', updated_at = now()
   where order_id = p_order_id and status = 'reserved'
  returning coupon_id into v_coupon;
  if found then
    update public.coupons set reserved_count = greatest(reserved_count - 1, 0) where id = v_coupon;
  end if;
end $$;

create or replace function public.use_coupon(p_order_id uuid) returns void
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_res public.coupon_reservations;
begin
  select * into v_res from public.coupon_reservations where order_id = p_order_id for update;
  if not found or v_res.status = 'used' then
    return;
  end if;
  update public.coupons
     set used_count = used_count + 1,
         reserved_count = case when v_res.status = 'reserved'
                               then greatest(reserved_count - 1, 0) else reserved_count end
   where id = v_res.coupon_id;
  update public.coupon_reservations set status = 'used', updated_at = now()
   where order_id = p_order_id;
end $$;

create or replace function public.open_incident(
  p_kind text, p_order_id uuid, p_provider_ref text, p_reported numeric,
  p_currency text, p_stored numeric, p_payload jsonb
) returns text
language plpgsql
set search_path = public, pg_temp
as $$
declare
  v_ticket text;
begin
  insert into public.incidents
    (kind, order_id, provider_ref, reported_amount, reported_currency,
     stored_amount, stored_currency, payload)
  values (p_kind, p_order_id, p_provider_ref,
          case when p_reported is not null and p_reported <> 'NaN'::numeric
                and abs(p_reported) < 10000000000 then round(p_reported, 2) end,
          left(p_currency, 10), p_stored, case when p_stored is not null then 'PHP' end, p_payload)
  returning ticket_no into v_ticket;
  return v_ticket;
end $$;

-- ---------------------------------------------------------------------------
-- create_order (§4 create-payment steps 1-5). Step 6, the PayMongo checkout,
-- happens in the Edge Function after this commits, then attach_checkout.
-- ---------------------------------------------------------------------------
create or replace function public.create_order(
  p_uid            uuid,
  p_product_id     uuid,
  p_method         text,
  p_coupon_code    text,
  p_ref_code       text,
  p_terms_accepted boolean
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_buyer      public.profiles;
  v_product    public.products;
  v_coupon     public.coupons;
  v_referrer   public.profiles;
  v_ref_id     uuid;
  v_discount   integer := 0;
  v_access_exp timestamptz;
  v_expires    timestamptz;
  v_open       record;
  v_order      public.orders;
begin
  if not coalesce(p_terms_accepted, false) then
    raise exception 'TERMS_REQUIRED';
  end if;
  if p_method is null or p_method not in ('gcash','maya','qrph','bank') then
    raise exception 'METHOD_INVALID';
  end if;

  -- Locking the buyer serialises double clicks from one account.
  select * into v_buyer from public.profiles where id = p_uid for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;
  if v_buyer.signup_completed_at is null then
    raise exception 'SIGNUP_INCOMPLETE';
  end if;

  select * into v_product from public.products where id = p_product_id and status = 'published';
  if not found then
    raise exception 'PRODUCT_NOT_FOUND';
  end if;
  if v_product.type = 'free' then
    raise exception 'PRODUCT_IS_FREE';
  end if;

  perform public.end_lapsed_enrollments(p_uid, p_product_id);
  if exists (select 1 from public.enrollments
              where user_id = p_uid and product_id = p_product_id and status = 'active') then
    raise exception 'ALREADY_OWNED';
  end if;

  if v_product.access_mode = 'exam_date' then
    v_access_exp := public.exam_date_ts();
    if v_access_exp is null or v_access_exp <= now() then
      raise exception 'EXAM_DATE_NOT_SET';
    end if;
  end if;

  -- An abandoned checkout for the same product gives its coupon back.
  for v_open in
    select id from public.orders
     where user_id = p_uid and product_id = p_product_id
       and status in ('created','awaiting_payment','awaiting_proof')
     for update
  loop
    update public.orders set status = 'expired' where id = v_open.id;
    perform public.release_coupon(v_open.id);
  end loop;

  if nullif(btrim(coalesce(p_coupon_code, '')), '') is not null then
    select * into v_coupon from public.coupons
     where code = upper(btrim(p_coupon_code)) for update;
    if not found or not v_coupon.active
       or (v_coupon.starts_at is not null and v_coupon.starts_at > now())
       or (v_coupon.expires_at is not null and v_coupon.expires_at <= now()) then
      raise exception 'COUPON_INVALID';
    end if;
    if v_coupon.product_ids is not null and not (p_product_id = any (v_coupon.product_ids)) then
      raise exception 'COUPON_NOT_APPLICABLE';
    end if;
    -- Percent discounts round to the nearest peso (10% of 49 = 5).
    v_discount := case v_coupon.type
                    when 'percent' then round(v_product.price_php * v_coupon.value / 100.0)::integer
                    else v_coupon.value end;
    if v_product.price_php - v_discount < 1 then
      raise exception 'COUPON_TOTAL_TOO_LOW';
    end if;
    update public.coupons set reserved_count = reserved_count + 1
     where id = v_coupon.id
       and (usage_limit is null or used_count + reserved_count < usage_limit);
    if not found then
      raise exception 'COUPON_UNAVAILABLE';
    end if;
  end if;

  -- Referrer: the one bound at signup wins over a first-touch code. Self,
  -- same email and same mobile are dropped silently.
  v_ref_id := v_buyer.referred_by_user_id;
  if v_ref_id is null and nullif(btrim(coalesce(p_ref_code, '')), '') is not null then
    select id into v_ref_id from public.profiles where ref_code = upper(btrim(p_ref_code));
  end if;
  if v_ref_id is not null then
    select * into v_referrer from public.profiles where id = v_ref_id;
    if v_referrer.id = p_uid
       or lower(v_referrer.email) = lower(v_buyer.email)
       or (v_referrer.mobile is not null and v_referrer.mobile = v_buyer.mobile) then
      v_ref_id := null;
    end if;
  end if;

  v_expires := now() + case when p_method = 'bank'
                            then public.setting_int('order_ttl_bank_h', 48) * interval '1 hour'
                            else public.setting_int('order_ttl_online_min', 60) * interval '1 minute' end;

  insert into public.orders
    (user_id, product_id, status, price_php, discount_php, coupon_id, total_php,
     referrer_user_id, ref_code, access_snapshot, method, expires_at, terms_accepted_at)
  values
    (p_uid, p_product_id,
     case when p_method = 'bank' then 'awaiting_proof' else 'created' end,
     v_product.price_php, v_discount, v_coupon.id, v_product.price_php - v_discount,
     v_ref_id, nullif(upper(btrim(coalesce(p_ref_code, ''))), ''),
     jsonb_build_object('type', v_product.type, 'title', v_product.title,
                        'subject', v_product.subject, 'access_mode', v_product.access_mode,
                        'attempts', v_product.attempts_per_purchase, 'expires_at', v_access_exp),
     p_method, v_expires, now())
  returning * into v_order;

  if v_coupon.id is not null then
    insert into public.coupon_reservations (order_id, coupon_id) values (v_order.id, v_coupon.id);
  end if;

  return jsonb_build_object(
    'order_id', v_order.id, 'order_no', v_order.order_no, 'status', v_order.status,
    'price_php', v_order.price_php, 'discount_php', v_order.discount_php,
    'total_php', v_order.total_php, 'coupon_code', v_coupon.code,
    'expires_at', v_order.expires_at, 'product_title', v_product.title,
    'referred', v_ref_id is not null);
end $$;

create or replace function public.attach_checkout(
  p_order_id uuid, p_provider_ref text, p_checkout_url text
) returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.orders
     set status = 'awaiting_payment', provider_ref = p_provider_ref, checkout_url = p_checkout_url
   where id = p_order_id and status = 'created';
  return found;
end $$;

-- ---------------------------------------------------------------------------
-- PayMongo webhook
-- ---------------------------------------------------------------------------
-- True when the event is new; a duplicate delivery returns false and the
-- webhook answers 200 without doing anything else.
create or replace function public.record_payment_event(
  p_event_id text, p_type text, p_payload jsonb, p_order_id uuid
) returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.payment_events (provider_event_id, type, payload, order_id)
  values (p_event_id, p_type, p_payload, p_order_id)
  on conflict (provider_event_id) do nothing;
  return found;
end $$;

create or replace function public.finish_payment_event(p_event_id text, p_outcome text)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  update public.payment_events set processed_at = now(), outcome = p_outcome
   where provider_event_id = p_event_id;
$$;

-- payment.paid: amount or currency off -> on_hold + incident, never fulfil.
create or replace function public.apply_payment_paid(
  p_order_id            uuid,
  p_amount_php          numeric,
  p_currency            text,
  p_provider_payment_id text,
  p_payload             jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order  public.orders;
  v_ticket text;
begin
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    v_ticket := public.open_incident('unmatched_payment', null, p_provider_payment_id,
                                     p_amount_php, p_currency, null, p_payload);
    return jsonb_build_object('outcome', 'unmatched', 'ticket', v_ticket);
  end if;

  if v_order.status = 'paid' then
    if v_order.provider_payment_id is not null
       and p_provider_payment_id is distinct from v_order.provider_payment_id then
      v_ticket := public.open_incident('duplicate_payment', v_order.id, p_provider_payment_id,
                                       p_amount_php, p_currency, v_order.total_php, p_payload);
      return jsonb_build_object('outcome', 'duplicate', 'ticket', v_ticket);
    end if;
    return jsonb_build_object('outcome', 'already_paid');
  end if;

  if v_order.status = 'refunded' then
    v_ticket := public.open_incident('out_of_order_status', v_order.id, p_provider_payment_id,
                                     p_amount_php, p_currency, v_order.total_php, p_payload);
    return jsonb_build_object('outcome', 'already_refunded', 'ticket', v_ticket);
  end if;

  update public.orders set provider_payment_id = coalesce(p_provider_payment_id, provider_payment_id)
   where id = v_order.id;

  if p_currency is null or upper(btrim(p_currency)) <> 'PHP' then
    update public.orders set status = 'on_hold' where id = v_order.id;
    v_ticket := public.open_incident('currency_mismatch', v_order.id, p_provider_payment_id,
                                     p_amount_php, p_currency, v_order.total_php, p_payload);
    perform public.write_audit(null, 'payments', 'order_on_hold', v_order.order_no,
                               jsonb_build_object('ticket', v_ticket, 'currency', p_currency));
    return jsonb_build_object('outcome', 'currency_mismatch', 'ticket', v_ticket);
  end if;

  if p_amount_php is null or p_amount_php = 'NaN'::numeric
     or round(p_amount_php, 2) <> v_order.total_php then
    update public.orders set status = 'on_hold' where id = v_order.id;
    v_ticket := public.open_incident('amount_mismatch', v_order.id, p_provider_payment_id,
                                     p_amount_php, p_currency, v_order.total_php, p_payload);
    perform public.write_audit(null, 'payments', 'order_on_hold', v_order.order_no,
                               jsonb_build_object('ticket', v_ticket, 'reported', p_amount_php,
                                                  'expected', v_order.total_php));
    return jsonb_build_object('outcome', 'amount_mismatch', 'ticket', v_ticket);
  end if;

  return public.fulfil_order(v_order.id, null, 'PayMongo payment.paid');
end $$;

-- ---------------------------------------------------------------------------
-- fulfil_order (§4): paid -> enrollment from the snapshot -> coupon use ->
-- referral reward (unique per order) -> receipt email -> audit.
-- p_actor null = system (webhook, reconciliation); an admin needs a reason.
-- A paid order for a product the buyer already holds is a duplicate charge:
-- it is marked paid, no second enrollment, and an incident opens for refund.
-- ---------------------------------------------------------------------------
create or replace function public.fulfil_order(p_order_id uuid, p_actor uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order    public.orders;
  v_buyer    public.profiles;
  v_referrer public.profiles;
  v_amount   integer;
  v_ref_row  uuid;
  v_dup      boolean := false;
  v_mode     text;
  v_ticket   text;
begin
  if p_actor is not null and nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;

  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  if v_order.status = 'paid' then
    return jsonb_build_object('outcome', 'already_paid', 'order_id', v_order.id);
  end if;
  if v_order.status = 'refunded' then
    raise exception 'ORDER_NOT_FULFILLABLE';
  end if;

  update public.orders set status = 'paid', paid_at = now() where id = v_order.id;
  select * into v_buyer from public.profiles where id = v_order.user_id;

  perform public.end_lapsed_enrollments(v_order.user_id, v_order.product_id);
  if exists (select 1 from public.enrollments
              where user_id = v_order.user_id and product_id = v_order.product_id
                and status = 'active') then
    v_dup := true;
    v_ticket := public.open_incident('duplicate_payment', v_order.id, v_order.provider_payment_id,
                                     v_order.total_php, 'PHP', v_order.total_php, null);
  else
    v_mode := coalesce(v_order.access_snapshot->>'access_mode', 'unlimited');
    insert into public.enrollments
      (user_id, product_id, source, order_id, access_mode, attempts_allowed, expires_at)
    values
      (v_order.user_id, v_order.product_id, 'purchase', v_order.id, v_mode,
       nullif(v_order.access_snapshot->>'attempts', '')::integer,
       case when v_mode = 'exam_date' then public.exam_date_ts() end);
  end if;

  perform public.use_coupon(v_order.id);

  if v_order.referrer_user_id is not null then
    v_amount := public.setting_int('referral_amount', 9);
    select * into v_referrer from public.profiles where id = v_order.referrer_user_id;
    if v_amount > 0 and found then
      insert into public.referrals
        (referrer_ref_code, referrer_user_id, buyer_user_id, buyer_masked, order_id,
         product_id, product_title, amount_php, reward_type, status)
      values
        (v_referrer.ref_code, v_referrer.id, v_order.user_id,
         coalesce(public.mask_email(v_buyer.email), '***'), v_order.id, v_order.product_id,
         coalesce(v_order.access_snapshot->>'title', 'Product'), v_amount,
         coalesce((select case when value in ('cash','credit') then value end
                     from public.settings where key = 'reward_type'), 'cash')::public.reward_type,
         'available')
      on conflict (order_id) do nothing
      returning id into v_ref_row;
      if v_ref_row is not null then
        insert into public.balance_ledger (user_id, amount_php, source, ref_id)
        values (v_referrer.id, v_amount, 'referral', v_ref_row);
        perform public.enqueue_email('E6', v_referrer.email,
          jsonb_build_object('name', v_referrer.display_name, 'amount', v_amount,
                             'product', v_order.access_snapshot->>'title',
                             'balance', public.balance_of(v_referrer.id),
                             'threshold', public.setting_int('payout_threshold', 100),
                             'ref_code', v_referrer.ref_code),
          'E6:' || v_ref_row);
      end if;
    end if;
  end if;

  if v_order.method is distinct from 'bank' then
    perform public.enqueue_email('E2', v_buyer.email,
      jsonb_build_object('name', v_buyer.display_name, 'order_no', v_order.order_no,
                         'product', v_order.access_snapshot->>'title',
                         'price', v_order.price_php, 'discount', v_order.discount_php,
                         'total', v_order.total_php, 'method', v_order.method,
                         'access', v_order.access_snapshot),
      'E2:' || v_order.id);
  end if;

  perform public.write_audit(p_actor, 'payments',
    case when p_actor is null then 'order_fulfilled' else 'manual_fulfil' end,
    v_order.order_no,
    jsonb_build_object('reason', p_reason, 'total', v_order.total_php,
                       'duplicate', v_dup, 'ticket', v_ticket,
                       'referral', v_ref_row is not null));

  return jsonb_build_object('outcome', 'fulfilled', 'order_id', v_order.id,
                            'duplicate', v_dup, 'ticket', v_ticket);
end $$;

create or replace function public.fail_order(p_order_id uuid, p_reason text) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  update public.orders set status = 'failed'
   where id = p_order_id and status in ('created','awaiting_payment','awaiting_proof');
  if not found then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  perform public.release_coupon(p_order_id);
  return jsonb_build_object('ok', true, 'noop', false, 'reason', p_reason);
end $$;

-- Job: unpaid orders past expires_at -> expired, coupon released. Orders with
-- proof under review (pending_approval) never expire.
create or replace function public.expire_orders() returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_n  integer := 0;
begin
  for v_id in
    select id from public.orders
     where status in ('created','awaiting_payment','awaiting_proof') and expires_at < now()
     for update skip locked
  loop
    update public.orders set status = 'expired' where id = v_id;
    perform public.release_coupon(v_id);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- ---------------------------------------------------------------------------
-- Bank deposits (§5)
-- ---------------------------------------------------------------------------
create or replace function public.submit_bank_proof(
  p_uid          uuid,
  p_order_id     uuid,
  p_bank         text,
  p_amount       integer,
  p_reference_no text,
  p_proof_path   text,
  p_sha256       text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order public.orders;
  v_buyer public.profiles;
  v_dep   uuid;
  v_dup   boolean;
  v_admin text;
begin
  select * into v_order from public.orders where id = p_order_id and user_id = p_uid for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  if v_order.method is distinct from 'bank' then
    raise exception 'METHOD_INVALID';
  end if;
  if v_order.status not in ('awaiting_proof','pending_approval') then
    raise exception 'ORDER_NOT_AWAITING_PROOF';
  end if;
  if v_order.status = 'awaiting_proof' and v_order.expires_at < now() then
    raise exception 'ORDER_EXPIRED';
  end if;
  if p_amount is null or p_amount <= 0 then
    raise exception 'AMOUNT_INVALID';
  end if;

  -- A replacement proof while one is pending supersedes the old one.
  update public.bank_deposits set status = 'superseded'
   where order_id = p_order_id and status = 'pending_approval';

  insert into public.bank_deposits
    (order_id, user_id, bank, amount_received, reference_no, proof_path, proof_sha256)
  values (p_order_id, p_uid, lower(p_bank), p_amount, btrim(p_reference_no), p_proof_path, lower(p_sha256))
  returning id into v_dep;

  update public.orders set status = 'pending_approval' where id = p_order_id;

  select exists (
    select 1 from public.bank_deposits d
     where d.id <> v_dep and d.order_id <> p_order_id
       and ((d.bank = lower(p_bank) and lower(d.reference_no) = lower(btrim(p_reference_no)))
         or d.proof_sha256 = lower(p_sha256))) into v_dup;

  select * into v_buyer from public.profiles where id = p_uid;
  perform public.enqueue_email('E3', v_buyer.email,
    jsonb_build_object('name', v_buyer.display_name, 'order_no', v_order.order_no,
                       'product', v_order.access_snapshot->>'title', 'amount', p_amount,
                       'bank', lower(p_bank), 'sla_hours', public.setting_int('bank_sla_hours', 24)),
    'E3:' || v_dep);
  for v_admin in select email from public.admins loop
    perform public.enqueue_email('A1', v_admin,
      jsonb_build_object('order_no', v_order.order_no, 'amount', p_amount,
                         'total', v_order.total_php, 'bank', lower(p_bank), 'duplicate', v_dup),
      'A1:' || v_dep || ':' || v_admin);
  end loop;

  return jsonb_build_object('deposit_id', v_dep, 'duplicate_warning', v_dup);
end $$;

create or replace function public.approve_deposit(p_deposit_id uuid, p_admin uuid) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_dep   public.bank_deposits;
  v_order public.orders;
  v_buyer public.profiles;
  v_extra integer;
begin
  select * into v_dep from public.bank_deposits where id = p_deposit_id for update;
  if not found then
    raise exception 'DEPOSIT_NOT_FOUND';
  end if;
  if v_dep.status <> 'pending_approval' then
    return jsonb_build_object('ok', true, 'noop', true, 'status', v_dep.status);
  end if;

  select * into v_order from public.orders where id = v_dep.order_id for update;
  if v_dep.amount_received < v_order.total_php then
    raise exception 'DEPOSIT_UNDERPAID';
  end if;

  update public.bank_deposits
     set status = 'approved', reviewed_by = p_admin, reviewed_at = now()
   where id = v_dep.id;

  perform public.fulfil_order(v_order.id, p_admin, 'Bank deposit approved');

  v_extra := v_dep.amount_received - v_order.total_php;
  if v_extra > 0 then
    insert into public.balance_ledger (user_id, amount_php, source, ref_id, note, created_by)
    values (v_order.user_id, v_extra, 'deposit_credit', v_dep.id,
            'Overpayment on ' || v_order.order_no, p_admin);
  end if;

  select * into v_buyer from public.profiles where id = v_order.user_id;
  perform public.enqueue_email('E4', v_buyer.email,
    jsonb_build_object('name', v_buyer.display_name, 'order_no', v_order.order_no,
                       'product', v_order.access_snapshot->>'title',
                       'amount', v_dep.amount_received, 'bank', v_dep.bank,
                       'credit', v_extra, 'access', v_order.access_snapshot),
    'E4:' || v_dep.id);
  perform public.write_audit(p_admin, 'payments', 'deposit_approved', v_order.order_no,
    jsonb_build_object('amount', v_dep.amount_received, 'bank', v_dep.bank, 'credit', v_extra));

  return jsonb_build_object('ok', true, 'noop', false, 'credit', v_extra);
end $$;

-- Underpaid: rejecting credits the full amount received to the balance (E12).
create or replace function public.reject_deposit(
  p_deposit_id uuid, p_admin uuid, p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_dep    public.bank_deposits;
  v_order  public.orders;
  v_buyer  public.profiles;
  v_credit integer := 0;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;
  select * into v_dep from public.bank_deposits where id = p_deposit_id for update;
  if not found then
    raise exception 'DEPOSIT_NOT_FOUND';
  end if;
  if v_dep.status <> 'pending_approval' then
    return jsonb_build_object('ok', true, 'noop', true, 'status', v_dep.status);
  end if;
  select * into v_order from public.orders where id = v_dep.order_id for update;

  update public.bank_deposits
     set status = 'rejected', reject_reason = btrim(p_reason),
         reviewed_by = p_admin, reviewed_at = now()
   where id = v_dep.id;

  update public.orders
     set status = 'awaiting_proof',
         expires_at = now() + public.setting_int('order_ttl_bank_h', 48) * interval '1 hour'
   where id = v_order.id and status = 'pending_approval';

  select * into v_buyer from public.profiles where id = v_order.user_id;
  if v_dep.amount_received < v_order.total_php then
    v_credit := v_dep.amount_received;
    insert into public.balance_ledger (user_id, amount_php, source, ref_id, note, created_by)
    values (v_order.user_id, v_credit, 'deposit_credit', v_dep.id,
            'Short deposit on ' || v_order.order_no, p_admin);
    perform public.enqueue_email('E12', v_buyer.email,
      jsonb_build_object('name', v_buyer.display_name, 'order_no', v_order.order_no,
                         'product', v_order.access_snapshot->>'title',
                         'received', v_dep.amount_received, 'total', v_order.total_php,
                         'short_by', v_order.total_php - v_dep.amount_received),
      'E12:' || v_dep.id);
  else
    perform public.enqueue_email('E5', v_buyer.email,
      jsonb_build_object('name', v_buyer.display_name, 'order_no', v_order.order_no,
                         'bank', v_dep.bank, 'reason', btrim(p_reason)),
      'E5:' || v_dep.id);
  end if;

  perform public.write_audit(p_admin, 'payments', 'deposit_rejected', v_order.order_no,
    jsonb_build_object('reason', btrim(p_reason), 'amount', v_dep.amount_received,
                       'bank', v_dep.bank, 'credit', v_credit));
  return jsonb_build_object('ok', true, 'noop', false, 'credit', v_credit);
end $$;

-- Job: admin reminder for deposits waiting more than half the SLA.
create or replace function public.deposit_sla_reminders() returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_dep   record;
  v_admin text;
  v_n     integer := 0;
begin
  for v_dep in
    select d.id, o.order_no, d.created_at from public.bank_deposits d
      join public.orders o on o.id = d.order_id
     where d.status = 'pending_approval'
       and d.created_at < now() - public.setting_int('bank_sla_hours', 24) * interval '30 minutes'
  loop
    for v_admin in select email from public.admins loop
      perform public.enqueue_email('A1', v_admin,
        jsonb_build_object('order_no', v_dep.order_no, 'reminder', true,
                           'submitted_at', v_dep.created_at),
        'A1R:' || v_dep.id || ':' || v_admin);
    end loop;
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- ---------------------------------------------------------------------------
-- Refunds (§10): only failed-but-charged and duplicate payments. Voids the
-- referral reward; revokes an enrollment only if this order granted it.
-- The PayMongo refund call happens in the Edge Function first.
-- ---------------------------------------------------------------------------
create or replace function public.refund_order(
  p_order_id uuid, p_admin uuid, p_reason text, p_issue_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_order public.orders;
  v_buyer public.profiles;
  v_ref   record;
  v_rev   integer;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;
  select * into v_order from public.orders where id = p_order_id for update;
  if not found then
    raise exception 'ORDER_NOT_FOUND';
  end if;
  if v_order.status = 'refunded' then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  if v_order.status not in ('paid','on_hold','failed','expired') then
    raise exception 'ORDER_NOT_REFUNDABLE';
  end if;

  update public.orders set status = 'refunded', refunded_at = now() where id = v_order.id;

  for v_ref in
    update public.referrals set status = 'void', voided_at = now()
     where order_id = v_order.id and status <> 'void'
    returning id, referrer_user_id, amount_php
  loop
    insert into public.balance_ledger (user_id, amount_php, source, ref_id, note, created_by)
    values (v_ref.referrer_user_id, -v_ref.amount_php, 'adjustment', v_ref.id,
            'Referral voided: refund of ' || v_order.order_no, p_admin);
  end loop;

  update public.enrollments
     set status = 'revoked', ended_at = now(), revoked_reason = 'Refund of ' || v_order.order_no
   where order_id = v_order.id and status = 'active';
  get diagnostics v_rev = row_count;

  update public.incidents set resolved_at = now(), resolved_by = p_admin
   where order_id = v_order.id and resolved_at is null;
  if p_issue_id is not null then
    update public.issues
       set status = 'refunded', resolution = btrim(p_reason), resolved_by = p_admin, resolved_at = now()
     where id = p_issue_id and status = 'open';
  end if;

  select * into v_buyer from public.profiles where id = v_order.user_id;
  perform public.enqueue_email('E8', v_buyer.email,
    jsonb_build_object('name', v_buyer.display_name, 'order_no', v_order.order_no,
                       'product', v_order.access_snapshot->>'title',
                       'amount', v_order.total_php, 'method', v_order.method,
                       'access_kept', v_rev = 0),
    'E8:' || v_order.id);
  perform public.write_audit(p_admin, 'payments', 'refund_issued', v_order.order_no,
    jsonb_build_object('reason', btrim(p_reason), 'amount', v_order.total_php,
                       'enrollment_revoked', v_rev > 0));
  return jsonb_build_object('ok', true, 'noop', false, 'enrollment_revoked', v_rev > 0);
end $$;

-- ---------------------------------------------------------------------------
-- Admin access changes (§11) and the referral ledger Void action (§7)
-- ---------------------------------------------------------------------------
create or replace function public.grant_access(
  p_admin uuid, p_user_id uuid, p_product_id uuid, p_source text,
  p_expires_at timestamptz, p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_product public.products;
  v_id      uuid;
  v_mode    text;
begin
  if p_source not in ('comp','credit') then
    raise exception 'SOURCE_INVALID';
  end if;
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;
  select * into v_product from public.products where id = p_product_id;
  if not found then
    raise exception 'PRODUCT_NOT_FOUND';
  end if;
  perform public.end_lapsed_enrollments(p_user_id, p_product_id);
  if exists (select 1 from public.enrollments
              where user_id = p_user_id and product_id = p_product_id and status = 'active') then
    raise exception 'ALREADY_OWNED';
  end if;

  v_mode := case when p_expires_at is not null then 'fixed' else v_product.access_mode end;
  insert into public.enrollments
    (user_id, product_id, source, access_mode, attempts_allowed, expires_at)
  values (p_user_id, p_product_id, p_source::public.enrollment_source, v_mode,
          v_product.attempts_per_purchase,
          case when p_expires_at is not null then p_expires_at
               when v_mode = 'exam_date' then public.exam_date_ts() end)
  returning id into v_id;

  perform public.write_audit(p_admin, 'access', 'grant_access',
    (select email from public.profiles where id = p_user_id),
    jsonb_build_object('product', v_product.title, 'source', p_source,
                       'reason', btrim(p_reason), 'enrollment_id', v_id));
  return jsonb_build_object('ok', true, 'enrollment_id', v_id);
end $$;

create or replace function public.revoke_access(
  p_admin uuid, p_enrollment_id uuid, p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_e public.enrollments;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;
  update public.enrollments
     set status = 'revoked', ended_at = now(), revoked_reason = btrim(p_reason)
   where id = p_enrollment_id and status = 'active'
  returning * into v_e;
  if not found then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  perform public.write_audit(p_admin, 'access', 'revoke_access',
    (select email from public.profiles where id = v_e.user_id),
    jsonb_build_object('product', (select title from public.products where id = v_e.product_id),
                       'reason', btrim(p_reason), 'enrollment_id', v_e.id));
  return jsonb_build_object('ok', true, 'noop', false);
end $$;

create or replace function public.void_referral(
  p_admin uuid, p_referral_id uuid, p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_r public.referrals;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;
  update public.referrals set status = 'void', voided_at = now(), notes = btrim(p_reason)
   where id = p_referral_id and status <> 'void'
  returning * into v_r;
  if not found then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  insert into public.balance_ledger (user_id, amount_php, source, ref_id, note, created_by)
  values (v_r.referrer_user_id, -v_r.amount_php, 'adjustment', v_r.id,
          'Referral voided: ' || btrim(p_reason), p_admin);
  perform public.write_audit(p_admin, 'referrals', 'referral_voided', v_r.referrer_ref_code,
    jsonb_build_object('referral_id', v_r.id, 'amount', v_r.amount_php, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'noop', false);
end $$;

-- ---------------------------------------------------------------------------
-- Exam date (§1): moving it moves every active exam_date enrollment.
-- ---------------------------------------------------------------------------
create or replace function public.set_exam_date(p_admin uuid, p_date date) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old text;
  v_n   integer;
begin
  if p_date is null or p_date <= current_date then
    raise exception 'EXAM_DATE_INVALID';
  end if;
  select value into v_old from public.settings where key = 'exam_date' for update;
  update public.settings set value = to_char(p_date, 'YYYY-MM-DD'), updated_at = now()
   where key = 'exam_date';
  update public.enrollments set expires_at = public.exam_date_ts()
   where status = 'active' and access_mode = 'exam_date';
  get diagnostics v_n = row_count;
  perform public.write_audit(p_admin, 'settings', 'exam_date_changed', 'exam_date',
    jsonb_build_object('from', v_old, 'to', to_char(p_date, 'YYYY-MM-DD'), 'enrollments_moved', v_n));
  return jsonb_build_object('ok', true, 'enrollments_moved', v_n);
end $$;

-- Job (nightly): end enrollments past their expiry.
create or replace function public.expire_enrollments() returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_n integer;
begin
  update public.enrollments set status = 'ended', ended_at = now()
   where status = 'active' and expires_at is not null and expires_at <= now();
  get diagnostics v_n = row_count;
  if v_n > 0 then
    perform public.write_audit(null, 'access', 'enrollments_expired', null,
                               jsonb_build_object('count', v_n));
  end if;
  return v_n;
end $$;

-- =======================================================================
-- 0021_fn_v2_learning.sql
-- =======================================================================
-- 0021_fn_v2_learning.sql
-- Exams (BACKEND_RULES.md §8): starting an attempt uses it, answers autosave
-- until ends_at, submit grades on the server and is idempotent, a job
-- auto-submits attempts past ends_at. Plus the public leaderboard.

-- Result shape shared by submit_attempt and its idempotent replay.
-- Passing: >= 70% overall and no subject below 50%.
create or replace function public.attempt_result(p_attempt public.attempts) returns jsonb
language sql stable
set search_path = public, pg_temp
as $$
  select jsonb_build_object(
    'attempt_id', p_attempt.id,
    'quiz_id', p_attempt.quiz_id,
    'attempt_no', p_attempt.attempt_no,
    'score', p_attempt.score,
    'total', p_attempt.total,
    'pct', case when p_attempt.total > 0
                then round(p_attempt.score * 100.0 / p_attempt.total)::integer else 0 end,
    'breakdown', coalesce(p_attempt.breakdown, '{}'::jsonb),
    'passed', p_attempt.total > 0
              and p_attempt.score * 100.0 / p_attempt.total >= 70
              and not exists (
                select 1 from jsonb_each(coalesce(p_attempt.breakdown, '{}'::jsonb)) b
                 where (b.value->>'total')::integer > 0
                   and (b.value->>'correct')::numeric * 100 / (b.value->>'total')::numeric < 50),
    'submitted_at', p_attempt.submitted_at,
    'auto_submitted', p_attempt.auto_submitted);
$$;

-- p_uid null = the system (auto-submit job).
create or replace function public.submit_attempt(
  p_attempt_id uuid, p_uid uuid, p_auto boolean default false
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_a         public.attempts;
  v_e         public.enrollments;
  v_score     integer;
  v_total     integer;
  v_breakdown jsonb;
  v_result    jsonb;
begin
  select * into v_a from public.attempts where id = p_attempt_id for update;
  if not found or (p_uid is not null and v_a.user_id <> p_uid) then
    raise exception 'ATTEMPT_NOT_FOUND';
  end if;
  if v_a.status = 'submitted' then
    return public.attempt_result(v_a);
  end if;

  -- Unanswered items count as wrong. Subject per question, falling back to
  -- the quiz subject.
  with q as (
    select u.qid, qs.correct_index,
           coalesce(qs.subject, case when z.subject in ('A','B') then z.subject end, 'ALL') as subj
      from unnest(v_a.question_ids) as u(qid)
      join public.questions qs on qs.id = u.qid
      join public.quizzes z on z.id = qs.quiz_id),
  g as (
    select q.subj, (aa.choice is not null and aa.choice = q.correct_index) as ok
      from q left join public.attempt_answers aa
        on aa.attempt_id = v_a.id and aa.question_id = q.qid),
  s as (
    select subj, count(*) filter (where ok) as c, count(*) as t from g group by subj)
  select coalesce(sum(c), 0)::integer, coalesce(sum(t), 0)::integer,
         coalesce(jsonb_object_agg(subj, jsonb_build_object('correct', c, 'total', t)), '{}'::jsonb)
    into v_score, v_total, v_breakdown
    from s;

  update public.attempts
     set status = 'submitted', submitted_at = now(), auto_submitted = coalesce(p_auto, false),
         score = v_score, total = v_total, breakdown = v_breakdown
   where id = v_a.id
  returning * into v_a;

  v_result := public.attempt_result(v_a);

  if v_a.enrollment_id is not null then
    select * into v_e from public.enrollments where id = v_a.enrollment_id;
    if v_e.attempts_allowed is not null and v_e.attempts_allowed - v_e.attempts_used = 1 then
      perform public.enqueue_email('E10',
        (select email from public.profiles where id = v_a.user_id),
        jsonb_build_object('name', (select display_name from public.profiles where id = v_a.user_id),
                           'quiz', (select title from public.quizzes where id = v_a.quiz_id),
                           'pct', v_result->'pct', 'breakdown', v_breakdown,
                           'attempts_left', 1, 'attempts_allowed', v_e.attempts_allowed),
        'E10:' || v_e.id);
    end if;
  end if;

  return v_result;
end $$;

create or replace function public.start_attempt(p_uid uuid, p_quiz_id uuid) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_quiz    public.quizzes;
  v_open    public.attempts;
  v_e       public.enrollments;
  v_free    boolean;
  v_ids     uuid[];
  v_no      integer;
  v_attempt public.attempts;
begin
  select * into v_quiz from public.quizzes where id = p_quiz_id and status = 'published';
  if not found then
    raise exception 'QUIZ_NOT_FOUND';
  end if;
  if not exists (select 1 from public.profiles where id = p_uid and signup_completed_at is not null) then
    raise exception 'SIGNUP_INCOMPLETE';
  end if;

  select * into v_open from public.attempts
   where user_id = p_uid and status = 'in_progress' for update;
  if found then
    if v_open.ends_at is not null and v_open.ends_at <= now() then
      perform public.submit_attempt(v_open.id, null, true);
    elsif v_open.quiz_id = p_quiz_id then
      return jsonb_build_object(
        'attempt_id', v_open.id, 'quiz_id', v_open.quiz_id, 'attempt_no', v_open.attempt_no,
        'started_at', v_open.started_at, 'ends_at', v_open.ends_at, 'server_now', now(),
        'question_ids', to_jsonb(v_open.question_ids), 'resumed', true);
    else
      raise exception 'ATTEMPT_IN_PROGRESS';
    end if;
  end if;

  v_free := exists (
    select 1 from public.pack_quizzes pq join public.products p on p.id = pq.product_id
     where pq.quiz_id = p_quiz_id and p.type = 'free' and p.status = 'published');

  if not v_free then
    update public.enrollments e set status = 'ended', ended_at = now()
     where e.user_id = p_uid and e.status = 'active'
       and e.expires_at is not null and e.expires_at <= now()
       and e.product_id in (select product_id from public.pack_quizzes where quiz_id = p_quiz_id);

    select e.* into v_e
      from public.enrollments e
      join public.pack_quizzes pq on pq.product_id = e.product_id
     where pq.quiz_id = p_quiz_id and e.user_id = p_uid and e.status = 'active'
       and (e.attempts_allowed is null or e.attempts_used < e.attempts_allowed)
     order by e.created_at
     limit 1
     for update of e;
    if not found then
      if exists (select 1 from public.enrollments e
                   join public.pack_quizzes pq on pq.product_id = e.product_id
                  where pq.quiz_id = p_quiz_id and e.user_id = p_uid
                    and e.attempts_allowed is not null and e.attempts_used >= e.attempts_allowed) then
        raise exception 'ATTEMPTS_USED';
      end if;
      raise exception 'NO_ACCESS';
    end if;

    -- Starting uses the attempt; the last one ends the enrollment now, while
    -- the attempt itself stays open until submitted.
    update public.enrollments
       set attempts_used = attempts_used + 1,
           status   = case when attempts_allowed is not null and attempts_used + 1 >= attempts_allowed
                           then 'ended' else status end,
           ended_at = case when attempts_allowed is not null and attempts_used + 1 >= attempts_allowed
                           then now() else ended_at end
     where id = v_e.id
    returning * into v_e;
  end if;

  select coalesce(array_agg(id order by question_number), '{}') into v_ids
    from public.questions where quiz_id = p_quiz_id and status = 'published';
  if cardinality(v_ids) = 0 then
    raise exception 'QUIZ_EMPTY';
  end if;

  select count(*) + 1 into v_no from public.attempts where user_id = p_uid and quiz_id = p_quiz_id;

  insert into public.attempts (user_id, quiz_id, enrollment_id, attempt_no, question_ids, ends_at)
  values (p_uid, p_quiz_id, v_e.id, v_no, v_ids,
          case when v_quiz.time_limit_sec > 0
               then now() + v_quiz.time_limit_sec * interval '1 second' end)
  returning * into v_attempt;

  return jsonb_build_object(
    'attempt_id', v_attempt.id, 'quiz_id', p_quiz_id, 'attempt_no', v_attempt.attempt_no,
    'started_at', v_attempt.started_at, 'ends_at', v_attempt.ends_at, 'server_now', now(),
    'question_ids', to_jsonb(v_ids), 'resumed', false,
    'attempts_allowed', v_e.attempts_allowed, 'attempts_used', v_e.attempts_used);
end $$;

-- Batch autosave, used for every change and for the offline queue sync:
-- p_answers = [{question_id, choice (int|null), flagged (bool)}].
-- Rejected once ends_at has passed (5s grace for the request in flight).
create or replace function public.save_answers(
  p_uid uuid, p_attempt_id uuid, p_answers jsonb
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_a public.attempts;
  v_n integer;
begin
  select * into v_a from public.attempts
   where id = p_attempt_id and user_id = p_uid for share;
  if not found then
    raise exception 'ATTEMPT_NOT_FOUND';
  end if;
  if v_a.status <> 'in_progress'
     or (v_a.ends_at is not null and now() > v_a.ends_at + interval '5 seconds') then
    raise exception 'ATTEMPT_CLOSED';
  end if;
  if jsonb_typeof(p_answers) <> 'array' then
    raise exception 'ANSWERS_INVALID';
  end if;

  insert into public.attempt_answers (attempt_id, question_id, choice, flagged, updated_at)
  select p_attempt_id, (x->>'question_id')::uuid,
         case when jsonb_typeof(x->'choice') = 'number' then (x->>'choice')::integer end,
         coalesce((x->>'flagged')::boolean, false), now()
    from jsonb_array_elements(p_answers) x
   where (x->>'question_id')::uuid = any (v_a.question_ids)
  on conflict (attempt_id, question_id) do update
     set choice = excluded.choice, flagged = excluded.flagged, updated_at = now();
  get diagnostics v_n = row_count;
  return jsonb_build_object('saved', v_n, 'saved_at', now());
end $$;

-- Job (every minute): submit attempts whose timer ran out.
create or replace function public.auto_submit_due() returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
  v_n  integer := 0;
begin
  for v_id in
    select id from public.attempts
     where status = 'in_progress' and ends_at is not null and ends_at < now()
     for update skip locked
  loop
    perform public.submit_attempt(v_id, null, true);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- Public leaderboard (§8): best submitted attempt per user, display name
-- only, for students who accepted the public_leaderboard consent. The
-- caller's own row is always included so "your rank" can be shown.
create or replace function public.leaderboard(p_quiz_id uuid, p_limit integer default 10)
returns table (rank bigint, display_name text, pct integer, is_me boolean, entrants bigint)
language sql stable
security definer
set search_path = public, pg_temp
as $$
  with best as (
    select distinct on (a.user_id)
           a.user_id, a.score::numeric / a.total as ratio,
           round(a.score * 100.0 / a.total)::integer as pct
      from public.attempts a
     where a.quiz_id = p_quiz_id and a.status = 'submitted' and a.total > 0
       and exists (select 1 from public.consents c
                    where c.user_id = a.user_id and c.type = 'public_leaderboard')
     order by a.user_id, a.score::numeric / a.total desc, a.submitted_at
  ),
  ranked as (
    select b.*, rank() over (order by b.ratio desc) as r, count(*) over () as n from best b
  )
  select r.r, coalesce(nullif(btrim(p.display_name), ''), 'Reviewee'), r.pct,
         r.user_id = auth.uid(), r.n
    from ranked r join public.profiles p on p.id = r.user_id
   where coalesce((select value from public.settings where key = 'leaderboard_mode'), 'public') <> 'off'
     and (r.r <= least(greatest(coalesce(p_limit, 10), 1), 50) or r.user_id = auth.uid())
   order by r.r, 2;
$$;

-- =======================================================================
-- 0022_fn_v2_payouts_jobs.sql
-- =======================================================================
-- 0022_fn_v2_payouts_jobs.sql
-- Payouts (BACKEND_RULES.md §7), the pg_cron schedule for the SQL-only jobs
-- (§4, §5, §8), and the final EXECUTE lockdown for every v2 routine.

-- ---------------------------------------------------------------------------
-- Payouts: the request and its negative ledger row commit together, which
-- locks the amount; the buyer row lock makes a double click a no-op.
-- ---------------------------------------------------------------------------
create or replace function public.request_payout(p_uid uuid) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_p       public.profiles;
  v_balance integer;
  v_min     integer := public.setting_int('payout_threshold', 100);
  v_id      uuid;
begin
  select * into v_p from public.profiles where id = p_uid for update;
  if not found then
    raise exception 'PROFILE_NOT_FOUND';
  end if;
  if v_p.mobile is null then
    raise exception 'MOBILE_REQUIRED';
  end if;
  if exists (select 1 from public.payouts where user_id = p_uid and status = 'requested') then
    raise exception 'PAYOUT_PENDING';
  end if;
  v_balance := public.balance_of(p_uid);
  if v_balance < v_min then
    raise exception 'BELOW_THRESHOLD';
  end if;

  insert into public.payouts (user_id, amount_php, mobile)
  values (p_uid, v_balance, v_p.mobile)
  returning id into v_id;
  insert into public.balance_ledger (user_id, amount_php, source, ref_id)
  values (p_uid, -v_balance, 'payout', v_id);
  update public.referrals set status = 'redeemed', redeemed_at = now()
   where referrer_user_id = p_uid and status = 'available';

  perform public.enqueue_email('E11', v_p.email,
    jsonb_build_object('name', v_p.display_name, 'amount', v_balance, 'mobile', v_p.mobile),
    'E11:' || v_id);
  perform public.write_audit(p_uid, 'referrals', 'payout_requested', v_p.ref_code,
                             jsonb_build_object('amount', v_balance, 'payout_id', v_id));
  return jsonb_build_object('ok', true, 'payout_id', v_id, 'amount', v_balance);
end $$;

create or replace function public.mark_payout_sent(
  p_payout_id uuid, p_admin uuid, p_gcash_ref text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_po public.payouts;
  v_p  public.profiles;
begin
  if nullif(btrim(coalesce(p_gcash_ref, '')), '') is null then
    raise exception 'GCASH_REF_REQUIRED';
  end if;
  update public.payouts
     set status = 'sent', gcash_ref = btrim(p_gcash_ref), sent_at = now(), handled_by = p_admin
   where id = p_payout_id and status = 'requested'
  returning * into v_po;
  if not found then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  select * into v_p from public.profiles where id = v_po.user_id;
  perform public.enqueue_email('E7', v_p.email,
    jsonb_build_object('name', v_p.display_name, 'amount', v_po.amount_php,
                       'mobile', v_po.mobile, 'gcash_ref', v_po.gcash_ref),
    'E7:' || v_po.id);
  perform public.write_audit(p_admin, 'referrals', 'payout_sent', v_p.ref_code,
    jsonb_build_object('amount', v_po.amount_php, 'gcash_ref', v_po.gcash_ref));
  return jsonb_build_object('ok', true, 'noop', false);
end $$;

-- A payout that failed (wrong number) goes back on the balance.
create or replace function public.reverse_payout(
  p_payout_id uuid, p_admin uuid, p_reason text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_po public.payouts;
begin
  if nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'REASON_REQUIRED';
  end if;
  update public.payouts
     set status = 'reversed', notes = btrim(p_reason), handled_by = p_admin
   where id = p_payout_id and status in ('requested','sent')
  returning * into v_po;
  if not found then
    return jsonb_build_object('ok', true, 'noop', true);
  end if;
  insert into public.balance_ledger (user_id, amount_php, source, ref_id, note, created_by)
  values (v_po.user_id, v_po.amount_php, 'payout_reversal', v_po.id, btrim(p_reason), p_admin);
  perform public.write_audit(p_admin, 'referrals', 'payout_reversed',
    (select ref_code from public.profiles where id = v_po.user_id),
    jsonb_build_object('amount', v_po.amount_php, 'reason', btrim(p_reason)));
  return jsonb_build_object('ok', true, 'noop', false);
end $$;

-- ---------------------------------------------------------------------------
-- pg_cron. Reconciliation with PayMongo and the outbox sender need HTTP and
-- are scheduled from the Edge Functions phase. Without pg_cron (some local
-- stacks) the schedule is skipped and the jobs can be run by hand.
-- ---------------------------------------------------------------------------
do $$
begin
  begin
    create extension if not exists pg_cron with schema pg_catalog;
  exception when others then
    raise notice 'pg_cron not available (%); jobs not scheduled', sqlerrm;
    return;
  end;
  perform cron.schedule('arkiprep-auto-submit',     '* * * * *',    'select public.auto_submit_due()');
  perform cron.schedule('arkiprep-expire-orders',   '* * * * *',    'select public.expire_orders()');
  perform cron.schedule('arkiprep-stale-sessions',  '*/5 * * * *',  'select public.end_stale_sessions()');
  perform cron.schedule('arkiprep-deposit-sla',     '*/15 * * * *', 'select public.deposit_sla_reminders()');
  -- 00:05 Asia/Manila
  perform cron.schedule('arkiprep-expire-enrollments', '5 16 * * *', 'select public.expire_enrollments()');
exception when others then
  raise notice 'pg_cron scheduling skipped: %', sqlerrm;
end $$;

-- ---------------------------------------------------------------------------
-- EXECUTE lockdown: every routine in public is service-role only, except the
-- public leaderboard.
-- ---------------------------------------------------------------------------
revoke execute on all functions in schema public from public, anon, authenticated;
grant execute on function public.leaderboard(uuid, integer) to anon, authenticated;

-- =======================================================================
-- 0023_setting_login_email_code.sql
-- =======================================================================
-- 0023_setting_login_email_code.sql
-- Whether the login email shows a 6-digit code. Free-plan Supabase sends
-- only a login link until custom SMTP unlocks the email template; while this
-- is 'off' the login page asks the student to click the link and hides the
-- code boxes. Set to 'on' once the template includes {{ .Token }}.

insert into public.settings (key, value, display_safe)
values ('login_email_code', 'off', true)
on conflict (key) do nothing;

-- =======================================================================
-- 0024_job_interests.sql
-- =======================================================================
-- 0024_job_interests.sql
-- "Work with us": people leave an email (required) and optionally a name,
-- area, note and résumé to be told when a role opens. Written only by the
-- careers-interest Edge Function (service role); no client can read or write.

create table public.job_interests (
  id          uuid primary key default gen_random_uuid(),
  email       text not null
              check (email = lower(btrim(email)) and char_length(email) <= 254
                     and email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  name        text check (char_length(name) <= 100),
  area        text check (area in ('question_writer','reviewer_writer','faculty','support','other')),
  message     text check (char_length(message) <= 2000),
  resume_path text,
  consent_at  timestamptz not null default now(),
  ip          text,
  notified_at timestamptz,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
-- One entry per email; submitting again updates it.
create unique index job_interests_email_key on public.job_interests (email);
create index job_interests_ip_idx on public.job_interests (ip, updated_at desc);

alter table public.job_interests enable row level security;
alter table public.job_interests force row level security;

-- Max 5 submissions per IP per hour. Returns the row id so the Edge Function
-- can attach the résumé it uploads under that id.
create or replace function public.job_interest_submit(
  p_email text, p_name text, p_area text, p_message text, p_ip text
) returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_id    uuid;
  v_new   boolean;
begin
  if v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' or char_length(v_email) > 254 then
    raise exception 'EMAIL_INVALID';
  end if;
  if p_ip is not null
     and (select count(*) from public.job_interests
           where ip = p_ip and updated_at > now() - interval '1 hour') >= 5 then
    raise exception 'RATE_LIMITED';
  end if;

  insert into public.job_interests (email, name, area, message, ip)
  values (v_email, nullif(left(btrim(coalesce(p_name, '')), 100), ''),
          nullif(p_area, ''), nullif(left(btrim(coalesce(p_message, '')), 2000), ''), p_ip)
  on conflict (email) do update
     set name = coalesce(excluded.name, job_interests.name),
         area = coalesce(excluded.area, job_interests.area),
         message = coalesce(excluded.message, job_interests.message),
         ip = excluded.ip, consent_at = now(), updated_at = now()
  returning id, (xmax = 0) into v_id, v_new;

  return jsonb_build_object('id', v_id, 'new', v_new);
end $$;

create or replace function public.job_interest_attach_resume(p_id uuid, p_path text)
returns void
language sql
security definer
set search_path = public, pg_temp
as $$
  update public.job_interests set resume_path = p_path, updated_at = now() where id = p_id;
$$;

revoke execute on function public.job_interest_submit(text, text, text, text, text) from public, anon, authenticated;
revoke execute on function public.job_interest_attach_resume(uuid, text) from public, anon, authenticated;

-- Private bucket for résumés, 5 MB, PDF/DOC/DOCX (the Edge Function checks
-- the same). Created only where a current Supabase Storage schema exists;
-- bare or stub Postgres images used in tests skip it.
do $$
begin
  if exists (select 1 from information_schema.columns
              where table_schema = 'storage' and table_name = 'buckets'
                and column_name = 'allowed_mime_types') then
    execute $i$
      insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
      values ('resumes', 'resumes', false, 5242880,
              array['application/pdf', 'application/msword',
                    'application/vnd.openxmlformats-officedocument.wordprocessingml.document'])
      on conflict (id) do nothing$i$;
  end if;
end $$;

-- =======================================================================
-- Backfill: profiles for auth users created before the signup trigger
-- =======================================================================
insert into public.profiles (id, email, ref_code)
select u.id, u.email, public.gen_ref_code()
  from auth.users u
on conflict (id) do nothing;

commit;

select 'all migrations applied' as result,
       (select count(*) from public.profiles) as profiles,
       (select count(*) from public.profiles p
          join public.admins a on a.email = lower(p.email)) as admins;
